### 2. Connection Processing Flow

```cpp

void ConnectionManager::processNewData(Connection* conn, uint32_t events) {
    if (conn->state_ == Connection::CONN_READING) {
        // Read data from socket into connection buffer
        // Parse enough of the request to find the Host header
        bool host_found = parseHostHeader(conn);

        if (host_found) {
            // Find the correct virtual host
            std::string host = extractHostname(conn->request_data_->headers["Host"]);
            Server* target_server = server_manager_->getServerForHost(host);

            if (target_server) {
                // Update connection with the correct server config
                conn->server_config_ = target_server->getConfig();

                // Let the server process the request with its own components
                target_server->processRequest(conn);
            } else {
                // No matching virtual host, use default server
                server_manager_->getDefaultServer()->processRequest(conn);
            }
        }
    }
}

// Extract hostname from Host header (e.g., "example.com:8080" -> "example.com")
std::string ConnectionManager::extractHostname(const std::string& host_header) {
    size_t pos = host_header.find(':');
    if (pos != std::string::npos) {
        return host_header.substr(0, pos);
    }
    return host_header;
}
```

### 3. Server Responsibilities

```cpp

void Server::processRequest(Connection* conn) {
    // At this point, the connection has been assigned to this server
    // and the Host header has been parsed

    // Complete parsing of the request if needed
    request_parser_.parseRequest(conn);

    // Route the request to the appropriate handler
    AHandler* handler = router_.routeRequest(conn->request_data_);
    conn->active_handler_ptr_ = handler;

    // Let the handler process the request
    handler->handle(conn);

    // Response will be sent by the connection manager
}
