```cpp

void Cluster::processConnection(Connection* conn, uint32_t events) {
    // Handle read events
    if (events & EPOLLIN) {
        // Use the centralized RequestParser to read and parse the request
        RequestParseResult result = request_parser_.parseRequest(conn);

        switch (result) {
            case REQUEST_COMPLETE:
                // Find the appropriate server based on Host header
                Server* target_server = findServerForRequest(*conn->request_data_);
                if (!target_server) {
                    target_server = default_server_;
                }

                // Let the server handle the request
                AHandler* handler = target_server->routeRequest(conn->request_data_);
                conn->active_handler_ptr_ = handler;
                handler->handle(conn);

                // Update connection state
                conn->state_ = Connection::CONN_WRITING;
                break;

            case REQUEST_INCOMPLETE:
                // Need more data, continue reading
                break;

            case REQUEST_ERROR:
                // Handle error (400 Bad Request)
                generate400Response(conn);
                conn->state_ = Connection::CONN_WRITING;
                break;
        }
    }

    // Handle write events
    if (events & EPOLLOUT && conn->state_ == Connection::CONN_WRITING) {
        response_writer_.writeResponse(conn);

        // Check if response is complete
        if (conn->write_buffer_offset_ == conn->write_buffer_.size()) {
            if (conn->is_keep_alive()) {
                // Reset for another request
                conn->reset_for_keep_alive();
            } else {
                // Close connection
                connection_manager_.closeConnection(conn);
            }
        }
    }
}

Server* Cluster::findServerForRequest(const HttpRequest& request) {
    // Check if Host header exists
    std::map<std::string, std::string>::const_iterator it = request.headers.find("Host");
    if (it == request.headers.end()) {
        return default_server_; // No Host header
    }

    // Extract hostname from Host header (remove port if present)
    std::string host = it->second;
    size_t pos = host.find(':');
    if (pos != std::string::npos) {
        host = host.substr(0, pos);
    }

    // Find matching server
    std::map<std::string, Server*>::const_iterator server_it = virtual_hosts_.find(host);
    if (server_it != virtual_hosts_.end()) {
        return server_it->second;
    }

    // No matching virtual host
    return default_server_;
}
