# Client Connection and Web Server Flow

## Client Connection Behavior

Yes, a client can (and often does) open multiple connections to the same web server:

1. **Browser Connection Pooling**: Modern browsers open 2-8 concurrent connections to optimize loading speed
2. **Multiple Tabs/Windows**: Each browser tab/window maintains its own connection pool 
3. **Domain Sharding**: When a site uses multiple subdomains pointing to the same server
4. **Different Services**: Client accessing different services (HTTP, HTTPS) on the same server

Each connection gets its own socket file descriptor, Connection object, and processing flow.

## Detailed Web Server Flow

### 1. Server Initialization
```cpp
// Server startup sequence
void WebServer::initialize() {
    // 1. Load and parse configuration
    parseConfigFile(config_path_);

    // 2. Create virtual servers from config
    for (const auto& config : server_configs_) {
        VirtualServer* vs = new VirtualServer(config);
        virtual_servers_.push_back(vs);

        // Register virtual host names in lookup map
        for (const auto& server_name : config.server_names) {
            virtual_host_map_[server_name] = vs;
        }

        // Remember default server for each port
        if (default_servers_.find(config.port) == default_servers_.end()) {
            default_servers_[config.port] = vs;
        }
    }

    // 3. Create epoll instance
    epoll_fd_ = epoll_create1(0);
    if (epoll_fd_ == -1) {
        throw std::runtime_error("Failed to create epoll instance");
    }

    // 4. Create listening sockets for each port
    for (const auto& port_entry : default_servers_) {
        int port = port_entry.first;
        int listen_fd = createListeningSocket(port);

        // Add listener to epoll
        struct epoll_event ev;
        ev.events = EPOLLIN;
        ev.data.fd = listen_fd;
        epoll_ctl(epoll_fd_, EPOLL_CTL_ADD, listen_fd, &ev);

        // Store mapping: listening_fd -> port
        listener_to_port_map_[listen_fd] = port;
    }

    // 5. Initialize shared components
    connection_manager_.initialize();
    request_parser_.initialize();

    // 6. Initialize handlers
    static_file_handler_.initialize();
    cgi_handler_.initialize();
    file_upload_handler_.initialize();
    response_writer_.initialize();
}
```

### 2. Event Loop
```cpp
void WebServer::run() {
    const int MAX_EVENTS = 64;
    struct epoll_event events[MAX_EVENTS];

    while (running_) {
        // 1. Clean up timed-out connections
        connection_manager_.cleanupTimedOutConnections();

        // 2. Wait for events (with timeout for periodic cleanup)
        int nfds = epoll_wait(epoll_fd_, events, MAX_EVENTS, 1000);

        // 3. Process events
        for (int i = 0; i < nfds; i++) {
            int fd = events[i].data.fd;

            // Check if this is a listening socket
            if (listener_to_port_map_.find(fd) != listener_to_port_map_.end()) {
                // It's a listening socket - accept new connection
                handleNewConnection(fd);
            } else {
                // Existing connection - get Connection object
                Connection* conn = connection_manager_.getConnectionByFd(fd);
                if (!conn) {
                    // Unknown FD - something went wrong
                    std::cerr << "Unknown fd " << fd << std::endl;
                    continue;
                }

                // Process based on current connection state
                if (events[i].events & EPOLLIN) {
                    handleReadEvent(conn);
                }

                if (events[i].events & EPOLLOUT) {
                    handleWriteEvent(conn);
                }

                if (events[i].events & (EPOLLERR | EPOLLHUP)) {
                    handleErrorEvent(conn);
                }
            }
        }
    }
}
```

### 3. New Connection Handling
```cpp
void WebServer::handleNewConnection(int listener_fd) {
    // 1. Accept the connection
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int client_fd = accept(listener_fd, (struct sockaddr*)&client_addr, &client_len);
    if (client_fd < 0) {
        // Handle error
        return;
    }

    // 2. Set non-blocking
    fcntl(client_fd, F_SETFL, O_NONBLOCK);

    // 3. Get the port this connection came in on
    int port = listener_to_port_map_[listener_fd];

    // 4. Get default server for this port
    VirtualServer* default_server = default_servers_[port];

    // 5. Create new Connection object
    Connection* conn = connection_manager_.createConnection(
        client_fd, 
        default_server->getConfig(), 
        default_server
    );

    // 6. Add to epoll with read interest
    struct epoll_event ev;
    ev.events = EPOLLIN;
    ev.data.fd = client_fd;
    epoll_ctl(epoll_fd_, EPOLL_CTL_ADD, client_fd, &ev);

    // 7. Log new connection
    logInfo("New connection from " + getClientAddressString(client_addr));
}
```

### 4. Read Event Handling
```cpp
void WebServer::handleReadEvent(Connection* conn) {
    // 1. Update activity timestamp
    conn->last_activity_ = time(NULL);

    // 2. Read data from socket
    char buffer[4096];
    ssize_t bytes_read = read(conn->client_fd_, buffer, sizeof(buffer));

    if (bytes_read <= 0) {
