        connection_manager_.closeConnection(conn);
        return;
    }

    // 3. Append data to connection buffer
    conn->read_buffer_.insert(conn->read_buffer_.end(), buffer, buffer + bytes_read);

    // 4. Parse request
    parseRequest(conn);
