### 5. Request Parsing
```cpp
void WebServer::parseRequest(Connection* conn) {
    // 1. State-based parsing
    while (true) {
        // Current state determines what we're parsing
        if (conn->request_data_ == NULL) {
            // First time - create request object
            conn->request_data_ = new HttpRequest();
        }

        if (!conn->request_data_->headers_complete) {
            // 2. Parse headers first
            ParseResult result = request_parser_.parseHeaders(conn);

            switch (result) {
                case PARSE_INCOMPLETE:
                    // Not enough data yet, wait for more
                    return;

                case PARSE_HEADERS_COMPLETE:
                    // Headers are complete - we can now check for virtual host
                    assignVirtualServer(conn);

                    // If request has a body, continue to body parsing
                    // Otherwise we can proceed to processing
                    if (requestHasBody(conn->request_data_)) {
                        continue;
                    } else {
                        // No body, request is complete
                        processCompleteRequest(conn);
                        return;
                    }

                case PARSE_ERROR:
                    // Malformed request - respond with 400 Bad Request
                    sendErrorResponse(conn, 400, "Bad Request");
                    return;
            }
        }
        else {
            // 3. Parse body
            ParseResult result = request_parser_.parseBody(conn);

            switch (result) {
                case PARSE_INCOMPLETE:
                    // Not enough data yet, wait for more
                    return;

                case PARSE_COMPLETE:
                    // Request is fully parsed
                    processCompleteRequest(conn);
                    return;

                case PARSE_ERROR:
                    // Malformed body - respond with 400 Bad Request
                    sendErrorResponse(conn, 400, "Bad Request");
                    return;
            }
        }
    }
}
