void WebServer::assignVirtualServer(Connection* conn) {
    // 1. Check if Host header exists
    auto it = conn->request_data_->headers.find("Host");
    if (it == conn->request_data_->headers.end()) {
        // No Host header - keep default server
        return;
    }

    // 2. Get hostname from Host header
    std::string host_header = it->second;
    std::string hostname = extractHostname(host_header); // Remove port if present

    // 3. Look up VirtualServer by hostname
    auto vs_it = virtual_host_map_.find(hostname);
    if (vs_it != virtual_host_map_.end()) {
        VirtualServer* vs = vs_it->second;

        // 4. Check if this virtual server listens on the correct port
        int request_port = getPortFromHostHeader(host_header);
        if (request_port == -1) {
            // No port specified in Host header, use connection port
            // (Could get this from listener_fd mapping)
            request_port = getConnectionPort(conn);
        }

        if (vs->getPort() == request_port) {
            // 5. Update connection's virtual server
            conn->virtual_server_ = vs;
            // Update server_config_ pointer (assuming you've changed it to pointer)
            conn->server_config_ = &vs->getConfig();
        }
    }
    // If no match found, keep using default server
