### 7. Complete Request Processing
```cpp
void WebServer::processCompleteRequest(Connection* conn) {
    // 1. Update connection state
    conn->state_ = Connection::CONN_PROCESSING;

    // 2. Get virtual server for this request
    VirtualServer* vs = conn->virtual_server_;

    // 3. Find matching location
    const LocationConfig* location = vs->matchLocation(conn->request_data_);

    // 4. Select appropriate handler
    AHandler* handler = NULL;

    if (location->isCgi()) {
        handler = &cgi_handler_;
    }
    else if (location->allowsUploads() && 
             (conn->request_data_->method == "POST" || 
              conn->request_data_->method == "PUT")) {
        handler = &file_upload_handler_;
    }
    else {
        handler = &static_file_handler_;
    }

    // 5. Store handler and location in connection
    conn->active_handler_ptr_ = handler;
    conn->matched_location_ = location;

    // 6. Let handler process the request
    HandlerResult result = handler->handle(conn);

    switch (result) {
        case HANDLER_DONE:
            // Handler finished immediately - prepare to send response
            prepareToSendResponse(conn);
            break;

        case HANDLER_ASYNC:
            // Handler will call back when done (e.g., for CGI)
            // Nothing to do now
            break;

        case HANDLER_ERROR:
            // Handler encountered an error
            sendErrorResponse(conn, 500, "Internal Server Error");
            break;
    }
}
