### 10. Error Handling and Connection Cleanup
```cpp
void WebServer::sendErrorResponse(Connection* conn, int status_code, const std::string& message) {
    // 1. Create error response
    if (!conn->response_data_) {
        conn->response_data_ = new HttpResponse();
    }

    conn->response_data_->status_code = status_code;
    conn->response_data_->status_message = message;

    // 2. Generate error page based on configured error pages or default
    VirtualServer* vs = conn->virtual_server_;
    std::string error_page = vs->getErrorPage(status_code);

    if (!error_page.empty()) {
        // Use configured error page
        static_file_handler_.serveErrorPage(conn, error_page);
    } else {
        // Generate default error page
        generateDefaultErrorPage(conn);
    }

    // 3. Prepare to send
    prepareToSendResponse(conn);
}

void ConnectionManager::closeConnection(Connection* conn) {
    // 1. Cleanup CGI resources if needed
    if (conn->cgi_pid_ > 0) {
        kill(conn->cgi_pid_, SIGTERM);
        conn->cgi_pid_ = -1;
    }

    if (conn->cgi_pipe_stdin_fd_ != -1) {
        close(conn->cgi_pipe_stdin_fd_);
        conn->cgi_pipe_stdin_fd_ = -1;
    }

    if (conn->cgi_pipe_stdout_fd_ != -1) {
        // Remove from epoll first
        epoll_ctl(epoll_fd_, EPOLL_CTL_DEL, conn->cgi_pipe_stdout_fd_, NULL);
        close(conn->cgi_pipe_stdout_fd_);
        conn->cgi_pipe_stdout_fd_ = -1;
    }

    // 2. Cleanup static file resources if needed
    if (conn->static_file_fd_ != -1) {
        close(conn->static_file_fd_);
        conn->static_file_fd_ = -1;
    }

    // 3. Remove from epoll
    epoll_ctl(epoll_fd_, EPOLL_CTL_DEL, conn->client_fd_, NULL);

    // 4. Close socket
    close(conn->client_fd_);

    // 5. Remove from active connections
    active_connections_.erase(conn->client_fd_);

    // 6. Delete Connection object
    delete conn;
}
