         it != port_to_virtual_server_.end(); ++it) {

        int port = it->first;

        // Get all hosts this port needs to bind to
        std::set<std::string> hosts_to_bind;
        for (size_t i = 0; i < it->second.size(); ++i) {
            hosts_to_bind.insert(it->second[i]->host_);
        }

        // Create a socket for each unique host:port combination
        for (std::set<std::string>::iterator host_it = hosts_to_bind.begin();
             host_it != hosts_to_bind.end(); ++host_it) {

            std::string host = *host_it;
            std::pair<std::string, int> bind_key(host, port);

            // Skip if we've already bound this combination
            if (bound_sockets.find(bind_key) != bound_sockets.end()) {
                continue;
            }

            // Create socket
            int listener_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
            if (listener_fd < 0) {
                std::cerr << "Failed to create listener socket for " << host << ":" << port << std::endl;
                return false;
            }

            // Set socket options
            int opt = 1;
            if (setsockopt(listener_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
                std::cerr << "Failed to set socket options for " << host << ":" << port << std::endl;
                close(listener_fd);
                return false;
            }

            // Bind to the specified host:port
            struct sockaddr_in addr;
            memset(&addr, 0, sizeof(addr));
            addr.sin_family = AF_INET;
            addr.sin_port = htons(port);

            if (host == "0.0.0.0") {
                addr.sin_addr.s_addr = INADDR_ANY;
            } else {
                addr.sin_addr.s_addr = inet_addr(host.c_str());
            }

            if (bind(listener_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
                std::cerr << "Failed to bind to " << host << ":" << port << std::endl;
                close(listener_fd);
                return false;
            }

            // Listen for connections
            if (listen(listener_fd, SOMAXCONN) < 0) {
                std::cerr << "Failed to listen on " << host << ":" << port << std::endl;
                close(listener_fd);
                return false;
            }

            // Store the socket fd
            bound_sockets[bind_key] = listener_fd;

            // Add to listener_fds_ vector
            listener_fds_.push_back(listener_fd);

            // Register with epoll
            if (!register_epoll_events(listener_fd, EPOLLIN)) {
                std::cerr << "Failed to register " << host << ":" << port << " with epoll" << std::endl;
                close(listener_fd);
                return false;
            }

            // Map this socket to its default virtual server (first in the list)
            listener_to_default_server_[listener_fd] = it->second[0];

            std::cout << "Listening on " << host << ":" << port << std::endl;
        }
    }

    return !bound_sockets.empty();
}
