## Enhanced Implementation

```cpp
bool VirtualServer::parse_listen(const std::string& value, VirtualServer& config) {
    // Extract host and port from the value
    std::string host_str;
    size_t colonPos = value.find(':');

    if (colonPos != std::string::npos) {
        host_str = value.substr(0, colonPos);
        std::istringstream iss(value.substr(colonPos + 1));
        if (!(iss >> config.port_)) {
            std::cerr << "Error parsing port in listen directive: " << value << std::endl;
            return false;
        }
    } else {
        // Just a port number
        std::istringstream iss(value);
        if (!(iss >> config.port_)) {
            std::cerr << "Error parsing port in listen directive: " << value << std::endl;
            return false;
        }
        host_str = DEFAULT_HOST;  // Default to all interfaces
    }

    // Always store the original host string (useful for logs/debugging)
    config.host_name_ = host_str;

    // Special case for "0.0.0.0" (INADDR_ANY) - no need to resolve
    if (host_str == "0.0.0.0") {
        config.host_ = host_str;
        return true;
    }

    // Resolve hostname to IP
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;  // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    // Convert port to string for getaddrinfo
    std::stringstream port_ss;
    port_ss << config.port_;

    int status = getaddrinfo(host_str.c_str(), port_ss.str().c_str(), &hints, &res);
    if (status != 0) {
        std::cerr << "Error resolving hostname '" << host_str 
                  << "': " << gai_strerror(status) << std::endl;
        return false;
    }

    // Convert the resolved address to string and store it
    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &((struct sockaddr_in*)res->ai_addr)->sin_addr, 
              ip_str, sizeof(ip_str));
    config.host_ = ip_str;

    // Free the linked list returned by getaddrinfo
    freeaddrinfo(res);

    return true;
}
```

