bool WebServer::setup_listener_sockets() {
    // Track successfully created sockets
    std::vector<int> created_fds;

    // Detect conflicting bind addresses (0.0.0.0 conflicts with specific IPs)
    std::map<int, std::string> wildcard_ports;
    std::map<int, std::string> specific_ports;

    // First pass: identify conflicts
    for (std::map<std::string, std::vector<VirtualServer*>>::iterator it = 
             endpoint_to_virtual_server_.begin();
         it != endpoint_to_virtual_server_.end(); ++it) {

        std::string endpoint = it->first;
        VirtualServer* server = it->second[0]; // Default server for this endpoint

        // Extract host and port from endpoint
        std::string host = server->host_;
        int port = server->port_;

        if (host == "0.0.0.0") {
            wildcard_ports[port] = endpoint;
        } else {
            specific_ports[port] = endpoint;
        }
    }

    // Second pass: create sockets (skip specific IPs if wildcard exists)
    for (std::map<std::string, std::vector<VirtualServer*>>::iterator it = 
             endpoint_to_virtual_server_.begin();
         it != endpoint_to_virtual_server_.end(); ++it) {

        std::string endpoint = it->first;
        VirtualServer* server = it->second[0]; // Default server for this endpoint

        // Extract host and port 
        std::string host = server->host_;
        int port = server->port_;

        // Skip if we have a wildcard socket on this port and this is a specific IP
        if (host != "0.0.0.0" && wildcard_ports.find(port) != wildcard_ports.end()) {
            std::cout << "Skipping " << endpoint << " - already covered by " 
                      << wildcard_ports[port] << std::endl;
            continue;
        }

        // Create socket
        int listener_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
        if (listener_fd < 0) {
            std::cerr << "Failed to create socket for " << endpoint << std::endl;
            goto error_cleanup;
        }

        // Set socket options
        int opt = 1;
        if (setsockopt(listener_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
            std::cerr << "Failed to set socket options for " << endpoint << std::endl;
            close(listener_fd);
            goto error_cleanup;
        }

        // Bind socket
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);

        if (host == "0.0.0.0") {
            addr.sin_addr.s_addr = INADDR_ANY;
        } else {
            addr.sin_addr.s_addr = inet_addr(host.c_str());
        }

        if (bind(listener_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            std::cerr << "Failed to bind to " << endpoint << std::endl;
            close(listener_fd);
            goto error_cleanup;
        }

        // Listen
        if (listen(listener_fd, SOMAXCONN) < 0) {
            std::cerr << "Failed to listen on " << endpoint << std::endl;
            close(listener_fd);
            goto error_cleanup;
        }

        // Register with epoll
        if (!register_epoll_events(listener_fd)) {
            std::cerr << "Failed to register " << endpoint << " with epoll" << std::endl;
            close(listener_fd);
            goto error_cleanup;
        }

        // Save in our maps for lookup during accept
        listener_to_default_server_[listener_fd] = server;
        listener_fds_.push_back(listener_fd);
        created_fds.push_back(listener_fd);

        std::cout << "Listening on " << endpoint << std::endl;
    }

    return true;

error_cleanup:
    // Clean up on error
    for (size_t i = 0; i < created_fds.size(); i++) {
        close(created_fds[i]);
    }
    return false;
}
