// Returns true if request is valid, false if an error response was set.
bool WebServer::validate_request_globally(Connection* conn) {
    HttpRequest* req = conn->request_data_;
    HttpResponse* res = conn->response_data_; // Assumes res is already allocated
    const VirtualServer* v_server = conn->virtual_server_;
    const Location* loc = conn->location_match_;

    // Ensure response_data is available to set errors
    if (!res) {
        log(LOG_CRITICAL, "validate_request_globally: conn->response_data_ is NULL for fd %d. Cannot proceed.", conn->client_fd_);
        // This is a severe internal issue. We might try to force a 500 if possible,
        // but it indicates a problem in handle_write's setup.
        // For now, let's assume handle_write ensures it's allocated.
        // If we can't set a response, we must indicate failure.
        return false; // Cannot validate or set error
    }

    // 1. Check if a location was matched (find_matching_location should have run in handle_read)
    if (!loc) {
        log(LOG_WARNING, "validate_request_globally: No matching location for URI '%s' for fd %d", req->path_.c_str(), conn->client_fd_);
        ErrorHandler::not_found(res, *v_server);
        return false;
    }

    // 2. Method Allowed for Matched Location
    if (!loc->allowed_methods_.empty()) {
        bool method_is_allowed = false;
        std::string allow_header_value;
        for (size_t i = 0; i < loc->allowed_methods_.size(); ++i) {
            if (i > 0) allow_header_value += ", ";
            allow_header_value += loc->allowed_methods_[i];
            if (loc->allowed_methods_[i] == req->method_) {
                method_is_allowed = true;
            }
        }
        if (!method_is_allowed) {
            log(LOG_WARNING, "validate_request_globally: Method '%s' not allowed for location '%s' (allows: %s) for fd %d",
                req->method_.c_str(), loc->path_.c_str(), allow_header_value.c_str(), conn->client_fd_);
            ErrorHandler::method_not_allowed(res, *v_server); // ErrorHandler sets status_code_ and status_message_
            res->headers_["Allow"] = allow_header_value;
            return false;
        }
    } else if (req->method_ != "GET" && req->method_ != "HEAD") {
        // Default behavior if allowed_methods is empty in config (e.g., only GET/HEAD)
        // Adjust this default as per your server's intended behavior for unspecified allowed_methods.
        log(LOG_WARNING, "validate_request_globally: Method '%s' not allowed for location '%s' (defaulting to GET/HEAD) for fd %d",
            req->method_.c_str(), loc->path_.c_str(), conn->client_fd_);
        ErrorHandler::method_not_allowed(res, *v_server);
        res->headers_["Allow"] = "GET, HEAD";
        return false;
    }

    // 3. Client Max Body Size (primarily for Content-Length)
    if (req->has_header("Content-Length")) {
        long long content_length_val = -1;
        std::istringstream iss(req->get_header("Content-Length"));
        if (!(iss >> content_length_val) || content_length_val < 0) {
            log(LOG_WARNING, "validate_request_globally: Invalid Content-Length value '%s' for fd %d", req->get_header("Content-Length").c_str(), conn->client_fd_);
            ErrorHandler::bad_request(res, *v_server);
            return false;
        }
        if (v_server->client_max_body_size_ > 0 && // 0 might mean unlimited
            static_cast<size_t>(content_length_val) > v_server->client_max_body_size_) {
            log(LOG_WARNING, "validate_request_globally: Content-Length %lld exceeds client_max_body_size %zu for fd %d",
                content_length_val, v_server->client_max_body_size_, conn->client_fd_);
            ErrorHandler::payload_too_large(res, *v_server);
            return false;
        }
    }
    // Note: For Transfer-Encoding: chunked, max body size check is more complex
    // and typically done during body parsing or before passing to CGI.

    // Add other global validations here (URI sanity, required headers for specific methods if not parser's job)

    log(LOG_DEBUG, "validate_request_globally: Request passed validation for fd %d", conn->client_fd_);
    return true;
}

