bool WebServer::validate_request_location(Connection* conn) {
    const Location* matching_location = conn->location_match_;
    const HttpRequest* request = conn->request_data_;
    HttpResponse* response = conn->response_data_; // Ensure this is allocated before calling
    const VirtualServer* v_server = conn->virtual_server_;

