            request->path_.c_str());
        ErrorHandler::generate_error_response(conn, codes::NOT_FOUND); // Assumes this sets response
        return false;
    }

    // 1. Process Location-Specific Redirects
    if (matching_location->return_code_ != 0 && !matching_location->return_url_.empty()) {
        log(LOG_DEBUG, "Location %s has a redirect to %s with code %d",
            matching_location->path_.c_str(), matching_location->return_url_.c_str(), matching_location->return_code_);
        response->status_code_ = matching_location->return_code_;
