             response->headers_["Content-Length"] = SSTR(response->body_.length());
        }
        return false; // Request handled by redirect
    }

    // 2. Check Allowed Methods
    const std::string& request_method = request->method_;
    if (!matching_location->allowed_methods_.empty()) {
        bool method_allowed = false;
        std::string allowed_methods_str;
        for (size_t i = 0; i < matching_location->allowed_methods_.size(); i++) {
            if (i > 0) allowed_methods_str += ", ";
            allowed_methods_str += matching_location->allowed_methods_[i];
            if (matching_location->allowed_methods_[i] == request_method) {
                method_allowed = true;
            }
        }
        if (!method_allowed) {
            log(LOG_DEBUG, "Method %s not allowed for location %s. Allowed: %s",
                request_method.c_str(), matching_location->path_.c_str(), allowed_methods_str.c_str());
            ErrorHandler::generate_error_response(conn, codes::METHOD_NOT_ALLOWED);
            response->headers_["Allow"] = allowed_methods_str;
            return false;
        }
    } else { // Default allowed methods if list is empty in config (e.g., GET, HEAD)
        if (request_method != "GET" && request_method != "HEAD") {
            log(LOG_DEBUG, "Method %s not allowed for location %s (defaulting to GET, HEAD)",
                request_method.c_str(), matching_location->path_.c_str());
            ErrorHandler::generate_error_response(conn, codes::METHOD_NOT_ALLOWED);
            response->headers_["Allow"] = "GET, HEAD";
            return false;
        }
    }

    // 3. Check Client Max Body Size
    if (request->has_header("Content-Length")) {
        long long content_length_val = -1;
        std::istringstream iss(request->get_header("Content-Length"));
        // The parser should have already validated the format of Content-Length.
        // If it's still not a valid number here, it's a parser oversight or internal error.
        // For robustness, we can check again.
        if (!(iss >> content_length_val) || content_length_val < 0) {
             log(LOG_WARNING, "Invalid Content-Length format '%s' encountered in validate_request_location.", request->get_header("Content-Length").c_str());
             ErrorHandler::generate_error_response(conn, codes::BAD_REQUEST);
             return false;
        }

        if (v_server->client_max_body_size_ > 0 && // 0 might mean unlimited or use a default
            static_cast<size_t>(content_length_val) > v_server->client_max_body_size_) {
            log(LOG_WARNING, "Content-Length %lld exceeds client_max_body_size %zu for location %s",
                content_length_val, v_server->client_max_body_size_, matching_location->path_.c_str());
            ErrorHandler::generate_error_response(conn, codes::PAYLOAD_TOO_LARGE);
            return false;
        }
    }
    // Note: For Transfer-Encoding: chunked, max body size check is more complex and typically
    // needs to be done incrementally as chunks arrive, or before passing to CGI.
    // If the parser has already aggregated a chunked body and can report its total size,
    // you could check request->body_.size() here if applicable.

    log(LOG_DEBUG, "Request for location %s passed validation.", matching_location->path_.c_str());
    return true;
}
