// ...existing code...
void WebServer::handle_connection_event(Connection* conn, int active_fd, uint32_t events) {
    if (!conn) {
        log(LOG_ERROR, "handle_connection_event called with null Connection for fd %d", active_fd);
        // Potentially remove active_fd from epoll if it's an unknown FD
        del_event_from_epoll(active_fd);
        return;
    }

    if (events & (EPOLLERR | EPOLLHUP)) {
        log(LOG_WARNING, "EPOLLERR or EPOLLHUP on fd %d for connection (client_fd %d)", active_fd, conn->client_fd_);
        // More specific error handling based on which FD it is (client vs pipe)
        if (active_fd == conn->client_fd_) {
            handle_error(conn); // Your existing client error handler
        } else if (active_fd == conn->cgi_pipe_stdin_fd_ || active_fd == conn->cgi_pipe_stdout_fd_) {
            // Handle CGI pipe error: likely means CGI crashed or closed pipes unexpectedly.
            // CgiHandler should probably take over to finalize CGI state and send error to client.
            log(LOG_WARNING, "Error on CGI pipe fd %d for client_fd %d", active_fd, conn->client_fd_);
            if (conn->active_handler_ == cgi_handler_) { // Assuming you have cgi_handler_ instance
                 // cgi_handler_->handle_pipe_error(conn, active_fd, events); // New method in CgiHandler
            } else {
                 handle_error(conn); // Fallback
            }
        } else {
            // Unknown FD associated with this connection? Should not happen.
            log(LOG_ERROR, "Unknown active_fd %d in handle_connection_event for client_fd %d", active_fd, conn->client_fd_);
            del_event_from_epoll(active_fd);
        }
        return;
    }

    // Determine if it's a client socket event or a CGI pipe event
    if (active_fd == conn->client_fd_) {
        if (events & EPOLLIN) {
            handle_read(conn);
        } else if (events & EPOLLOUT) {
            handle_write(conn);
        }
    } else if (conn->active_handler_ == cgi_handler_) { // Check if CgiHandler is active for this connection
