             log(LOG_WARNING, "Unhandled event %u on CGI pipe fd %d for client_fd %d", events, active_fd, conn->client_fd_);
        }
    } else {
        log(LOG_WARNING, "Event on non-client fd %d for connection (client_fd %d) without active CgiHandler", active_fd, conn->client_fd_);
        // This FD should probably be closed and removed from epoll.
