void WebServer::handle_connection_event(Connection* conn, int active_fd, uint32_t epoll_events) {
    if (!conn) {
        log(LOG_ERROR, "handle_connection_event: Null connection for fd %d", active_fd);
        remove_fd_from_epoll(active_fd); // Your helper to call epoll_ctl_del
        if (active_fd != -1) close(active_fd);
        return;
    }

    conn->last_activity_ = time(NULL);

    if (epoll_events & (EPOLLERR | EPOLLHUP)) {
        log(LOG_WARNING, "EPOLLERR/EPOLLHUP on fd %d for client %d. State: %d", active_fd, conn->client_fd_, conn->state_);
        // Let the current state handler try to deal with it, or transition to error
        // For CGI, CgiHandler should be notified to clean up its pipes/process.
        if (conn->state_ == codes::CONN_CGI_AWAITING_IO && conn->active_handler_ == cgi_handler_) {
            // cgi_handler_->handle_cgi_error_or_hup(conn, active_fd, this); // CgiHandler cleans up, sets error response
        } else {
            handle_error(conn); // Generic error handling
        }
        return;
    }

    switch (conn->state_) {
        case codes::CONN_READING_REQUEST:
            if (active_fd == conn->client_fd_ && (epoll_events & EPOLLIN)) {
                handle_read(conn); // Parses request. If complete, might change state to CONN_PROCESSING_REQUEST
            }
            break;

        case codes::CONN_PROCESSING_REQUEST:
            // This state is for when WebServer has a fully parsed request
            // and needs to choose a handler and call its initial 'handle' method.
            // This state might be very brief.
            // After calling handler->handle(), state might change to CONN_SENDING_RESPONSE (for static files)
            // or CONN_CGI_AWAITING_IO (for CGI).
            // This logic is likely within handle_read's completion or a separate step.
            // For now, let's assume handle_read transitions state appropriately.
            // If handle_write was previously used for this, it needs rethinking.
            // Let's assume handle_read, upon successful parse, calls a new function:
            // process_parsed_request(conn); which then calls choose_handler and handler->handle().
            // process_parsed_request would set the next state.
            log(LOG_DEBUG, "In CONN_PROCESSING_REQUEST for client %d (should be handled by request processing flow)", conn->client_fd_);
            // This state might not see direct epoll events unless a handler sets it and waits.
            break;

        case codes::CONN_CGI_AWAITING_IO:
            if (conn->active_handler_ == cgi_handler_) {
                // Delegate entirely to CgiHandler. It knows about active_fd and conn->cgi_handler_state_
                cgi_handler_->process_cgi_io(conn, active_fd, epoll_events, this);
                // CgiHandler will change conn->cgi_handler_state_ and, when done,
                // will change conn->state_ to CONN_SENDING_RESPONSE.
            } else {
                log(LOG_ERROR, "State CONN_CGI_AWAITING_IO but CgiHandler not active for client %d", conn->client_fd_);
                handle_error(conn);
            }
            break;

        case codes::CONN_SENDING_RESPONSE:
            if (active_fd == conn->client_fd_ && (epoll_events & EPOLLOUT)) {
                handle_write(conn); // Sends response (static, or CGI response prepared by CgiHandler)
                                    // handle_write will transition to CONN_READING_REQUEST (keep-alive) or CONN_CLOSING.
            }
            break;

        case codes::CONN_ERROR_OCCURRED:
             // This state implies an error response is being or needs to be sent.
             // Often, handle_error() would set this state and prepare an error response.
             // Then, it would ensure the client socket is monitored for EPOLLOUT to send it.
            if (active_fd == conn->client_fd_ && (epoll_events & EPOLLOUT)) {
                handle_write(conn); // Send the error response
            }
            break;

        case codes::CONN_CLOSING:
            // Should not receive events in this state if properly removed from epoll.
            log(LOG_WARNING, "Received event for fd %d in CONN_CLOSING state for client %d.", active_fd, conn->client_fd_);
            conn_manager_->close_connection(conn); // Ensure it's fully closed and removed.
            break;

        default:
            log(LOG_ERROR, "Unhandled connection state %d for fd %d, client %d", conn->state_, active_fd, conn->client_fd_);
            handle_error(conn);
            break;
    }
}
