// New private helper function
bool CgiHandler::validate_and_prepare_cgi_request(Connection* conn) {
    // 1. Check redirect (same as StaticFileHandler)
    if (process_location_redirect(conn)) {
        return false;  // Redirect response was set up, stop processing
    }

    // Extract request data
    const std::string& request_uri = conn->request_data_->uri_;
    const std::string& request_method = conn->request_data_->method_;
    const Location* location = conn->location_match_;

    // This check should be logical OR (if method is not GET AND it's not POST)
    // Original: if (request_method != "GET" || request_method != "POST")
    // Corrected:
    if (request_method != "GET" && request_method != "POST") {
        ErrorHandler::generate_error_response(conn, codes::METHOD_NOT_ALLOWED);
        conn->response_data_->headers_["Allow"] = "GET, POST";
        return false;
    }

    // 3. URI Format Check (can't execute a directory)
    if (!request_uri.empty() && request_uri[request_uri.length() - 1] == '/') {
        log(LOG_ERROR, "URI is a directory, cannot execute: %s",
            request_uri.c_str());
        ErrorHandler::generate_error_response(conn, codes::BAD_REQUEST);
        return false;
    }

    // 4. Script Path Resolution
    // Assuming parse_absolute_path is a member or accessible helper
    conn->script_path_ = parse_absolute_path(conn);
    // The local script_path variable is shadowed by the member, prefer using conn->script_path_ directly
    // std::string script_path = conn->script_path_; // This line can be removed if using conn->script_path_ below

    if (conn->script_path_.empty()) {
        log(LOG_ERROR, "Failed to determine CGI script path for URI: %s", request_uri.c_str());
        ErrorHandler::generate_error_response(conn, codes::INTERNAL_SERVER_ERROR);
        return false;
    }

    // 5. Script Extension Check
    bool is_valid_extension = false;
    std::string extension;
    size_t dot_pos = conn->script_path_.find_last_of('.');
    if (dot_pos != std::string::npos) {
        extension = conn->script_path_.substr(dot_pos + 1);
        // --CHECK - Check against allowed extensions from location/server config if available
        // For now, hardcoded:
        if (extension == "php" || extension == "py" || extension == "sh") {
            is_valid_extension = true;
        }
    }

    if (!is_valid_extension) {
        log(LOG_ERROR, "Invalid CGI script extension '%s' for script '%s'", extension.c_str(), conn->script_path_.c_str());
        ErrorHandler::generate_error_response(conn, codes::FORBIDDEN);
        return false;
    }

    // 6. Script Existence Check
    struct stat file_info;
    if (stat(conn->script_path_.c_str(), &file_info) == -1) {
        if (errno == ENOENT) {
            log(LOG_ERROR, "CGI script '%s' not found", conn->script_path_.c_str());
            ErrorHandler::generate_error_response(conn, codes::NOT_FOUND);
        } else {
            log(LOG_ERROR, "Failed to access CGI script '%s': %s", conn->script_path_.c_str(), strerror(errno));
            ErrorHandler::generate_error_response(conn,
                                                  codes::INTERNAL_SERVER_ERROR);
        }
        return false;
    }

    // 7. Script Type Validation
    if (!S_ISREG(file_info.st_mode)) {
        log(LOG_ERROR, "CGI script '%s' is not a regular file", conn->script_path_.c_str());
        ErrorHandler::generate_error_response(conn, codes::FORBIDDEN);
        return false;
    }

    // 8. Script Permission Check
    if (!(file_info.st_mode & S_IXUSR)) { // Check for user execute permission
        log(LOG_ERROR, "CGI script '%s' is not executable",
            conn->script_path_.c_str());
        ErrorHandler::generate_error_response(conn, codes::FORBIDDEN);
        return false;
    }

    // Content-Length checks for POST are important but seem to be handled by RequestParser.
    // If they were to be re-introduced here, ensure they are correct.
    // The commented-out section for Content-Length check (step 9) is extensive.
    // If RequestParser already validates this robustly (including max_body_size),
    // then it's fine to omit here. Otherwise, it should be reinstated and corrected.

    log(LOG_DEBUG, "CGI request validated for script: %s", conn->script_path_.c_str());
    return true; // All checks passed
}

