bool WebServer::setup_signal_handlers() {
    struct sigaction sa;
    // For SIGINT, SIGTERM, SIGPIPE, your current signal_handler might be fine
    // if it only cares about the signal number.
    sa.sa_handler = signal_handler; // This is WebServer::signal_handler
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART; // SA_RESTART is good for these

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log(LOG_ERROR, "Failed to set up SIGINT handler");
        return false;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log(LOG_ERROR, "Failed to set up SIGTERM handler");
        return false;
    }

    // For SIGPIPE, the default action is to terminate the process.
    // Handling it (even if just to log or ignore) can be useful.
    // Or, you can set it to SIG_IGN if you handle write errors explicitly.
    // sa.sa_handler = SIG_IGN; // Option 1: Ignore SIGPIPE
    // sa.sa_flags = 0; // No SA_RESTART needed if ignoring
    // Option 2: Use your generic handler (as you have it)
    if (sigaction(SIGPIPE, &sa, NULL) < 0) {
		log(LOG_ERROR, "Failed to set up SIGPIPE handler");
		return false;
	}

    // Now, set up SIGCHLD
    // You might want a different handler function for SIGCHLD
    // or modify your existing signal_handler to accommodate it.
    // Let's assume you'll add a case for SIGCHLD in WebServer::signal_handler
    // or create a dedicated one like sigchld_handler_function.

    struct sigaction sa_chld;
    // If WebServer::signal_handler will handle SIGCHLD:
    sa_chld.sa_handler = signal_handler;
    // If you use SA_SIGINFO for SIGCHLD to get child status directly:
    // sa_chld.sa_sigaction = your_siginfo_handler;
    // sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP | SA_SIGINFO;
    sigemptyset(&sa_chld.sa_mask);
    // SA_RESTART is generally good.
    // SA_NOCLDSTOP prevents SIGCHLD for child stop/continue, usually desired.
    sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP;


    if (sigaction(SIGCHLD, &sa_chld, NULL) < 0) {
        log(LOG_ERROR, "Failed to set up SIGCHLD handler");
        return false;
    }

    return true;
}

