    if (signal == SIGINT || signal == SIGTERM) {
        // It's generally safer to set a flag here and let the main loop
        // handle the shutdown cleanly, rather than calling get_instance()->shutdown()
        // directly from a signal handler, due to reentrancy concerns with complex functions.
        // For example:
