        // Log after initiating shutdown, but be mindful of what's safe to call from a handler.
        // Simple logging might be okay, but complex operations are risky.
        // A common pattern is to write a single byte to a self-pipe to wake up the event loop.
        log(LOG_INFO, "Received shutdown signal. Initiating shutdown...");
    } else if (signal == SIGCHLD) {
        // Reap zombie processes
        int saved_errno = errno; // Preserve errno
        while (waitpid(-1, NULL, WNOHANG) > 0) {
            // Child reaped. You could log here if desired.
            log(LOG_DEBUG, "SIGCHLD handler: Reaped a child process.");
        }
        errno = saved_errno; // Restore errno
    } else if (signal == SIGPIPE) {
        // SIGPIPE is sent when writing to a pipe or socket that has been closed
        // by the reading end. The default action is to terminate the process.
        // Handling it prevents termination. Your application should already
        // be checking for errors (like EPIPE) from write() calls.
        log(LOG_WARNING, "Received SIGPIPE. This usually means a client disconnected during a write.");
        // No specific action needed here if write errors are handled properly.
    }
}
