            log(LOG_DEBUG, "CGI: stdout pipe would block for client %d. Will retry.", conn->client_fd_);
            conn->cgi_read_buffer_.resize(original_size); // Revert resize
            return; // Remain in current state, wait for next EPOLLIN
        }
        // Actual read error
        log(LOG_ERROR, "CGI: Failed to read from stdout pipe for client %d: %s", conn->client_fd_, strerror(errno));
        ErrorHandler::generate_error_response(conn, codes::INTERNAL_SERVER_ERROR); // Or BAD_GATEWAY
        cleanup_cgi_resources(conn, true); // Kill child, close pipes
        conn->cgi_handler_state_ = codes::CGI_HANDLER_ERROR;
        conn->state_ = codes::CONN_WRITING; // To send error response
        return;
    }

    // Resize buffer to actual data read
    conn->cgi_read_buffer_.resize(original_size + bytes_read);

    if (bytes_read > 0) {
        log(LOG_DEBUG, "CGI: Read %zd bytes from stdout for client %d. Total buffer: %zu",
            bytes_read, conn->client_fd_, conn->cgi_read_buffer_.size());
        parse_cgi_output(conn); // This might change conn->cgi_handler_state_
    }
    // Note: parse_cgi_output might have set state to CGI_HANDLER_ERROR or CGI_HANDLER_COMPLETE

    // Check for completion or error conditions
    bool eof_received = (bytes_read == 0);

    if (conn->cgi_handler_state_ == codes::CGI_HANDLER_ERROR) {
        log(LOG_DEBUG, "CGI: Error state set by parser for client %d. Finalizing.", conn->client_fd_);
        // ErrorHandler and cleanup should have been called by parse_cgi_output
        // Ensure conn->state_ is set to send the error response.
        conn->state_ = codes::CONN_WRITING;
        return;
    }

    if (eof_received) {
        log(LOG_DEBUG, "CGI: EOF received from stdout for client %d.", conn->client_fd_);
        if (conn->cgi_handler_state_ == codes::CGI_HANDLER_READING_FROM_PIPE && !conn->cgi_read_buffer_.empty()) {
            // EOF before headers were fully parsed. This is a malformed response.
            log(LOG_WARNING, "CGI: EOF received before headers fully parsed for client %d. Buffer content: %.*s",
                conn->client_fd_, static_cast<int>(conn->cgi_read_buffer_.size()), conn->cgi_read_buffer_.data());
            ErrorHandler::generate_error_response(conn, codes::BAD_GATEWAY); // CGI script error
            conn->cgi_handler_state_ = codes::CGI_HANDLER_ERROR; // Mark as error
        } else if (conn->cgi_handler_state_ == codes::CGI_HANDLER_HEADERS_PARSED) {
