            // Any remaining data in cgi_read_buffer_ is part of the body.
            // parse_cgi_output (if called on last chunk before EOF) would have moved it.
            // If cgi_read_buffer_ still has data, it means the last chunk before EOF was not fully parsed
            // or parse_cgi_output didn't consume it because it was waiting for CRLF for a header.
            // For simplicity, if headers are parsed, we assume any remaining buffer is body.
            if (!conn->cgi_read_buffer_.empty()) {
                 conn->response_data_->body_.insert(conn->response_data_->body_.end(),
                                                    conn->cgi_read_buffer_.begin(),
                                                    conn->cgi_read_buffer_.end());
