        conn->cgi_handler_state_ = codes::CGI_HANDLER_COMPLETE;
    }

    if (conn->cgi_handler_state_ == codes::CGI_HANDLER_COMPLETE) {
        log(LOG_INFO, "CGI: Response processing complete for client %d. Total body size: %zu",
            conn->client_fd_, conn->response_data_->body_.size());
