        conn->conn_state_ = codes::CONN_WRITING; // Ready to send response
        return;
    }

    // If not complete and not an error, we are waiting for more data.
    log(LOG_DEBUG, "CGI: Still processing for client %d (state: %d), waiting for more data.",
        conn->client_fd_, conn->cgi_handler_state_);
}

void CgiHandler::parse_cgi_output(Connection* conn) {
    log(LOG_DEBUG, "CGI: Parsing output buffer (size %zu) for client %d, current state: %d",
        conn->cgi_read_buffer_.size(), conn->client_fd_, conn->cgi_handler_state_);

    std::vector<char>& buffer = conn->cgi_read_buffer_;

    // 1. Parse Headers
    if (conn->cgi_handler_state_ == codes::CGI_HANDLER_READING_FROM_PIPE) {
        while (!buffer.empty()) {
            std::vector<char>::iterator line_end_it =
                std::search(buffer.begin(), buffer.end(), CRLF, &CRLF[2]);

            if (line_end_it == buffer.end()) {
                // No complete header line found in current buffer
                log(LOG_DEBUG, "CGI: Incomplete header line for client %d. Waiting for more data.", conn->client_fd_);
                return; // Need more data
            }

            if (line_end_it == buffer.begin()) { // Empty line (CRLFCRLF)
                log(LOG_DEBUG, "CGI: End of headers found for client %d.", conn->client_fd_);
                buffer.erase(buffer.begin(), buffer.begin() + 2); // Consume CRLF
                conn->cgi_handler_state_ = codes::CGI_HANDLER_HEADERS_PARSED;
                break; // Move to body parsing
            }

            std::string header_line(buffer.begin(), line_end_it);
            // log(LOG_TRACE, "CGI: Header line for client %d: %s", conn->client_fd_, header_line.c_str());

            size_t colon_pos = header_line.find(':');
            if (colon_pos == std::string::npos || colon_pos == 0) {
                log(LOG_ERROR, "CGI: Invalid header line for client %d: '%s'", conn->client_fd_, header_line.c_str());
                ErrorHandler::generate_error_response(conn, codes::BAD_GATEWAY); // Malformed response from CGI
                cleanup_cgi_resources(conn, true);
                conn->cgi_handler_state_ = codes::CGI_HANDLER_ERROR;
                return;
            }

            std::string name = header_line.substr(0, colon_pos);
            std::string value = header_line.substr(colon_pos + 1);

            // Trim leading whitespace from value
            size_t value_start = value.find_first_not_of(" \t");
            value = (value_start == std::string::npos) ? "" : value.substr(value_start);

            // Normalize header name (lowercase) and validate
            for (size_t i = 0; i < name.length(); ++i) {
                unsigned char c = static_cast<unsigned char>(name[i]);
                if (!(isalnum(c) || strchr("!#$%&'*+-.^_`|~", c))) {
                     log(LOG_ERROR, "CGI: Invalid char '%c' in header name for client %d: %s", c, conn->client_fd_, name.c_str());
                     ErrorHandler::generate_error_response(conn, codes::BAD_GATEWAY);
                     cleanup_cgi_resources(conn, true);
                     conn->cgi_handler_state_ = codes::CGI_HANDLER_ERROR;
                     return;
                }
                name[i] = std::tolower(c);
            }

            // Handle specific headers like 'status' if needed for project
            if (name == "status") {
                // Parse status code from value, e.g., "200 OK" or just "200"
                // For simplicity, assuming value is just the code for now
                try {
                    conn->response_data_->status_code_ = std::stoi(value);
                } catch (const std::exception& e) {
                    log(LOG_WARNING, "CGI: Could not parse Status header value '%s' for client %d: %s",
                        value.c_str(), conn->client_fd_, e.what());
                    // Default to 200 or let it be if already set
                }
            } else {
                conn->response_data_->headers_[name] = value;
            }
            buffer.erase(buffer.begin(), line_end_it + 2); // Consume header line + CRLF
        }
    }

    // If still waiting for headers after loop (buffer became empty mid-header)
    if (conn->cgi_handler_state_ == codes::CGI_HANDLER_READING_FROM_PIPE) {
        log(LOG_DEBUG, "CGI: Still waiting for complete headers for client %d.", conn->client_fd_);
        return; // Need more data
    }

    // 2. Parse Body (if headers are parsed)
    if (conn->cgi_handler_state_ == codes::CGI_HANDLER_HEADERS_PARSED) {
        std::string cl_str = conn->response_data_->get_header("content-length");
        if (!cl_str.empty()) {
            size_t content_length;
            try {
                unsigned long cl_val = std::stoul(cl_str); // Use stoul for unsigned
                if (cl_val > MAX_CGI_BODY_SIZE) { // Define MAX_CGI_BODY_SIZE
                    log(LOG_ERROR, "CGI: Content-Length %lu exceeds MAX_CGI_BODY_SIZE for client %d", cl_val, conn->client_fd_);
                    throw std::out_of_range("Content-Length too large");
                }
                content_length = static_cast<size_t>(cl_val);
            } catch (const std::exception& e) {
                log(LOG_ERROR, "CGI: Invalid Content-Length '%s' for client %d: %s", cl_str.c_str(), conn->client_fd_, e.what());
                ErrorHandler::generate_error_response(conn, codes::BAD_GATEWAY);
                cleanup_cgi_resources(conn, true);
                conn->cgi_handler_state_ = codes::CGI_HANDLER_ERROR;
                return;
            }

            size_t needed = content_length - conn->response_data_->body_.size();
            size_t available_in_buffer = buffer.size();
            size_t to_copy = std::min(needed, available_in_buffer);

            if (to_copy > 0) {
                conn->response_data_->body_.insert(conn->response_data_->body_.end(),
                                                   buffer.begin(), buffer.begin() + to_copy);
                buffer.erase(buffer.begin(), buffer.begin() + to_copy);
                log(LOG_DEBUG, "CGI: Copied %zu bytes to body for client %d. Total body: %zu, Expected: %zu",
                    to_copy, conn->client_fd_, conn->response_data_->body_.size(), content_length);
            }

            if (conn->response_data_->body_.size() >= content_length) {
                log(LOG_DEBUG, "CGI: Content-Length met for client %d.", conn->client_fd_);
                if (conn->response_data_->body_.size() > content_length) {
                    log(LOG_WARNING, "CGI: Received more data than Content-Length for client %d. Truncating.", conn->client_fd_);
                    conn->response_data_->body_.resize(content_length); // Truncate if too much
                }
                conn->cgi_handler_state_ = codes::CGI_HANDLER_COMPLETE;
            } else {
                log(LOG_DEBUG, "CGI: Waiting for more body data for client %d (got %zu, need %zu total).",
                    conn->client_fd_, conn->response_data_->body_.size(), content_length);
                // Need more data, return
            }
        } else {
            // No Content-Length: append all current buffer data to body.
            // EOF in handle_cgi_read will signal final completion.
            if (!buffer.empty()) {
                log(LOG_DEBUG, "CGI: No Content-Length. Appending %zu bytes from buffer to body for client %d.",
                    buffer.size(), conn->client_fd_);
                conn->response_data_->body_.insert(conn->response_data_->body_.end(),
                                                   buffer.begin(), buffer.end());
                buffer.clear();
            }
            // State remains CGI_HANDLER_HEADERS_PARSED. Waiting for EOF or more data.
        }
    }
    // If state became CGI_HANDLER_COMPLETE or CGI_HANDLER_ERROR, handle_cgi_read will finalize.
}

