void CgiHandler::cleanup_cgi_resources(Connection* conn, bool kill_child_process) {
    WebServer* web_server = WebServer::get_instance(); // Assuming it's safe to call

    // Unregister and close stdin pipe if open
    if (conn->cgi_pipe_stdin_fd_ != -1) {
        if (web_server) {
            // If it was registered for EPOLLOUT, it might need specific unregistration
            // For simplicity, ConnectionManager handles unregistration by FD.
            web_server->get_conn_manager()->unregister_pipe(conn->cgi_pipe_stdin_fd_);
        }
        close(conn->cgi_pipe_stdin_fd_);
        conn->cgi_pipe_stdin_fd_ = -1;
        log(LOG_DEBUG, "CGI: Cleaned up stdin_fd for client %d", conn->client_fd_);
    }

    // Unregister and close stdout pipe if open
    if (conn->cgi_pipe_stdout_fd_ != -1) {
        if (web_server) {
            web_server->get_conn_manager()->unregister_pipe(conn->cgi_pipe_stdout_fd_);
        }
        close(conn->cgi_pipe_stdout_fd_);
        conn->cgi_pipe_stdout_fd_ = -1;
        log(LOG_DEBUG, "CGI: Cleaned up stdout_fd for client %d", conn->client_fd_);
    }

    // Kill child process if requested and PID is valid
    if (kill_child_process && conn->cgi_pid_ > 0) {
        log(LOG_INFO, "CGI: Killing child process %d for client %d due to error or cleanup.", conn->cgi_pid_, conn->client_fd_);
        kill(conn->cgi_pid_, SIGKILL); // Consider SIGTERM first for graceful shutdown if scripts support it
        // waitpid(conn->cgi_pid_, NULL, WNOHANG); // SIGCHLD handler should reap it
        conn->cgi_pid_ = -1;
    }
