    // --- Essential CGI Variables ---
    // REQUEST_METHOD
    env_vars_str.push_back("REQUEST_METHOD=" + conn->request_data_->method_);
    // SCRIPT_NAME (Path to the script)
    env_vars_str.push_back("SCRIPT_NAME=" + conn->script_path_); // Or conn->request_data_->uri_ depending on interpretation
    // SERVER_PROTOCOL
    env_vars_str.push_back("SERVER_PROTOCOL=" + conn->request_data_->version_);
    // SERVER_SOFTWARE (Your webserver name/version)
    env_vars_str.push_back("SERVER_SOFTWARE=webserv/1.0"); // Example

    // --- Variables based on request type and content ---
    if (conn->request_data_->method_ == "GET" && !conn->request_data_->query_string_.empty()) {
        env_vars_str.push_back("QUERY_STRING=" + conn->request_data_->query_string_);
    } else if (conn->request_data_->method_ == "POST") {
        // CONTENT_TYPE
        std::string content_type = conn->request_data_->get_header("content-type");
        if (!content_type.empty()) {
            env_vars_str.push_back("CONTENT_TYPE=" + content_type);
        }
        // CONTENT_LENGTH
        std::string content_length = conn->request_data_->get_header("content-length");
        if (!content_length.empty()) {
            env_vars_str.push_back("CONTENT_LENGTH=" + content_length);
        } else if (!conn->request_data_->body_.empty()) {
            // If body is present but no header, calculate it (though client should send it)
            std::stringstream ss;
            ss << conn->request_data_->body_.size();
            env_vars_str.push_back("CONTENT_LENGTH=" + ss.str());
