    // env_vars_str.push_back("SERVER_PORT=" + port_ss.str());

    // --- HTTP Headers (prefixed with HTTP_) ---
    for (std::map<std::string, std::string>::const_iterator it = conn->request_data_->headers_.begin();
         it != conn->request_data_->headers_.end(); ++it) {
        std::string header_name_env = "HTTP_";
        for (size_t i = 0; i < it->first.length(); ++i) {
            char c = it->first[i];
            if (c == '-') {
                header_name_env += '_';
            } else {
                header_name_env += std::toupper(static_cast<unsigned char>(c));
            }
        }
        env_vars_str.push_back(header_name_env + "=" + it->second);
    }

    // Convert std::string vector to char* vector for execve
    for (size_t i = 0; i < env_vars_str.size(); ++i) {
        envp.push_back(const_cast<char*>(env_vars_str[i].c_str()));
    }
    envp.push_back(NULL); // Null-terminate the array

    // Note: The std::vector<std::string> env_vars_str MUST remain in scope
    // or its underlying char* data pointed to by envp will be invalid.
    // For execve, this is fine because execve replaces the process image.
    // If you were to use this envp vector after this function returns (without execve),
    // you'd need to manage the lifetime of the strings more carefully (e.g., dynamic allocation).

    return envp;
}

void CgiHandler::execute_cgi_script(Connection* conn) {
    char* script_path_cstr = const_cast<char*>(conn->script_path_.c_str());

    // Argument list for the script. For many simple CGIs, just the script path is enough.
    // Some CGIs might be designed to take arguments, but that's less common for basic web CGIs.
    // If your script is, e.g., a Python script, argv[0] might be "/usr/bin/python" and argv[1] script_path_cstr.
    // For now, assuming the script itself is directly executable:
    char* const argv[] = {script_path_cstr, NULL};

    // Create the environment for the CGI script
    // This std::vector<std::string> holds the actual "NAME=VALUE" strings.
    // Its lifetime needs to be managed if envp_char_array is used beyond this immediate scope
    // without an execve call. However, since execve replaces the process, this is fine.
    std::vector<std::string> cgi_env_strings; // To store "NAME=VALUE"
    std::vector<char*> envp_char_array;    // To store char* for execve

    // Populate cgi_env_strings (example, expand with more CGI variables)
    cgi_env_strings.push_back("REQUEST_METHOD=" + conn->request_data_->method_);
    cgi_env_strings.push_back("SCRIPT_NAME=" + conn->script_path_);
    cgi_env_strings.push_back("SERVER_PROTOCOL=" + conn->request_data_->version_);
    cgi_env_strings.push_back("SERVER_SOFTWARE=webserv/1.0"); // Example

    if (conn->request_data_->method_ == "GET" && !conn->request_data_->query_string_.empty()) {
        cgi_env_strings.push_back("QUERY_STRING=" + conn->request_data_->query_string_);
    }
    // Add CONTENT_TYPE, CONTENT_LENGTH for POST
    if (conn->request_data_->method_ == "POST") {
        std::string ct = conn->request_data_->get_header("content-type");
        if (!ct.empty()) cgi_env_strings.push_back("CONTENT_TYPE=" + ct);
        std::string cl = conn->request_data_->get_header("content-length");
        if (!cl.empty()) cgi_env_strings.push_back("CONTENT_LENGTH=" + cl);
    }
    // Add all HTTP_ headers
    for (std::map<std::string, std::string>::const_iterator it = conn->request_data_->headers_.begin();
         it != conn->request_data_->headers_.end(); ++it) {
        std::string header_name_env = "HTTP_";
        for (size_t i = 0; i < it->first.length(); ++i) {
            char c = it->first[i];
            header_name_env += (c == '-') ? '_' : std::toupper(static_cast<unsigned char>(c));
        }
        cgi_env_strings.push_back(header_name_env + "=" + it->second);
    }
    // ... add other necessary CGI variables (SERVER_NAME, SERVER_PORT, REMOTE_ADDR, etc.)

    // Convert vector of std::string to vector of char*
    for (size_t i = 0; i < cgi_env_strings.size(); ++i) {
        envp_char_array.push_back(const_cast<char*>(cgi_env_strings[i].c_str()));
    }
    envp_char_array.push_back(NULL); // Null-terminate

    // Execute the CGI script
    if (execve(script_path_cstr, argv, envp_char_array.data()) == -1) {
        // Log the error before exiting. The parent won't see this log directly,
        // but it's good for debugging if you can capture child's stderr.
        // The parent will know execve failed because the pipe will close or
        // waitpid will indicate an error.
        log(LOG_ERROR, "CHILD: Failed to execute CGI script '%s': %s", script_path_cstr,
            strerror(errno));
        // Write a minimal error to stdout so parent might see it as a malformed CGI response
        write(STDOUT_FILENO, "Status: 500 Internal Server Error\r\n\r\nExecVE Failed", 52);
        _exit(EXIT_FAILURE);  // Exit child process on exec failure
    }
}

