    // env_vars_str.push_back("SERVER_PORT=" + port_ss.str());

    // --- HTTP Headers (prefixed with HTTP_) ---
    for (std::map<std::string, std::string>::const_iterator it = conn->request_data_->headers_.begin();
         it != conn->request_data_->headers_.end(); ++it) {
        std::string header_name_env = "HTTP_";
        for (size_t i = 0; i < it->first.length(); ++i) {
            char c = it->first[i];
            if (c == '-') {
                header_name_env += '_';
            } else {
                header_name_env += std::toupper(static_cast<unsigned char>(c));
