// Helper function to convert a string to lowercase
static std::string to_lower_case(const std::string& str) {
    std::string lower_str = str;
    std::transform(lower_str.begin(), lower_str.end(), lower_str.begin(),
                   [](unsigned char c){ return std::tolower(c); });
    return lower_str;
}

std::string HttpRequest::get_header(const std::string& name) const {
    std::string lower_name = to_lower_case(name);
    std::map<std::string, std::string>::const_iterator it = headers_.find(lower_name);
    if (it != headers_.end()) {
        return it->second;
    }
    return ""; // Or throw an exception, or return an optional, depending on desired behavior
}

void HttpRequest::set_header(const std::string& name, const std::string& value) {
    std::string lower_name = to_lower_case(name);
    headers_[lower_name] = value;
}

