// ...existing code...
void CgiHandler::cleanup_cgi_resources(Connection* conn, bool kill_child) {
    WebServer* web_server = WebServer::get_instance();

    // Attempt to reap the child process and get its status
    if (conn->cgi_pid_ > 0) {
        if (kill_child) {
            log(LOG_DEBUG, "CGI: Killing child process %d for client %d",
                conn->cgi_pid_, conn->client_fd_);
            if (kill(conn->cgi_pid_, SIGKILL) == -1) {
                log(LOG_WARNING, "CGI: Failed to send SIGKILL to child %d: %s", conn->cgi_pid_, strerror(errno));
            }
        }

        int status;
        pid_t result = waitpid(conn->cgi_pid_, &status, WNOHANG);

        if (result == conn->cgi_pid_) {
            // Child process has terminated
            if (WIFEXITED(status)) {
                int exit_code = WEXITSTATUS(status);
                log(LOG_DEBUG,
                    "CGI: Child process %d exited normally with status %d for client %d.",
                    conn->cgi_pid_, exit_code, conn->client_fd_);
                // If execve failed, your child calls _exit(EXIT_FAILURE).
                // This exit_code would be EXIT_FAILURE.
                // If the CGI script itself exited with a non-zero status, that would also be captured here.
            } else if (WIFSIGNALED(status)) {
                log(LOG_WARNING,
                    "CGI: Child process %d was terminated by signal %d for client %d.",
                    conn->cgi_pid_, WTERMSIG(status), conn->client_fd_);
            }
            conn->cgi_pid_ = -1; // Mark as reaped
        } else if (result == 0) {
            // Child has not terminated yet.
            // If kill_child was true, SIGKILL should be effective quickly.
            // If kill_child was false, the script might still be running (e.g. timeout scenario pending).
            log(LOG_DEBUG,
                "CGI: Child process %d has not exited yet (WNOHANG) for client %d.",
                conn->cgi_pid_, conn->client_fd_);
            // You might need a separate mechanism to handle/kill lingering children if they don't exit
            // after a timeout, but SIGKILL in the kill_child path should usually suffice.
        } else if (result == -1) {
            // Error calling waitpid
            log(LOG_ERROR, "CGI: Error calling waitpid for child %d: %s. Client %d.",
                conn->cgi_pid_, strerror(errno), conn->client_fd_);
            if (errno == ECHILD) { // No such child, or already reaped
                conn->cgi_pid_ = -1;
            }
        }
    }

    if (conn->cgi_pipe_stdin_fd_ != -1) {
        web_server->get_conn_manager()->unregister_pipe(
            conn->cgi_pipe_stdin_fd_); // Unregister before closing
        close(conn->cgi_pipe_stdin_fd_);
        conn->cgi_pipe_stdin_fd_ = -1;
    }

    if (conn->cgi_pipe_stdout_fd_ != -1) {
        web_server->get_conn_manager()->unregister_pipe(
            conn->cgi_pipe_stdout_fd_); // Unregister before closing
        close(conn->cgi_pipe_stdout_fd_);
        conn->cgi_pipe_stdout_fd_ = -1;
    }

    conn->cgi_read_buffer_.clear();
    log(LOG_DEBUG, "CGI resources cleaned up for client %d.", conn->client_fd_);
}
