void WebServer::match_host_header(Connection* conn) {
    if (!conn || !conn->request_data_ || !conn->default_virtual_server_) {
        log(LOG_ERROR, "match_host_header: Invalid connection or data.");
        // conn->virtual_server_ should already be default_virtual_server_ or NULL if creation failed
        return;
    }

    // Get Host header value from the request
    std::string request_host_header_val = conn->request_data_->get_header("Host");
    std::string target_hostname = request_host_header_val;

    if (target_hostname.empty()) {
        // No Host header. conn->virtual_server_ is already set to conn->default_virtual_server_.
        log(LOG_DEBUG, "No Host header. Using default virtual server for %s:%d",
            conn->virtual_server_->host_.c_str(), conn->virtual_server_->port_);
        return;
    }

    // Strip port number from Host header if present
    size_t colon_pos = target_hostname.find(':');
    if (colon_pos != std::string::npos) {
        target_hostname = target_hostname.substr(0, colon_pos);
    }

    // The connection's default_virtual_server_ tells us the port and listen IP
    // this connection is associated with.
    int listener_port = conn->default_virtual_server_->port_;
    std::string listener_host_ip = conn->default_virtual_server_->host_; // IP from 'listen' directive

    VirtualServer* matched_vs = NULL;

    // 1. Check servers listening on the specific IP:Port of the connection
    std::map<int, std::map<std::string, std::vector<VirtualServer*> > >::const_iterator port_it =
        port_to_hosts_.find(listener_port);

    if (port_it != port_to_hosts_.end()) {
        const std::map<std::string, std::vector<VirtualServer*> >& hosts_on_port = port_it->second;

        // Check specific listener IP
        std::map<std::string, std::vector<VirtualServer*> >::const_iterator host_ip_it =
            hosts_on_port.find(listener_host_ip);
        if (host_ip_it != hosts_on_port.end()) {
            const std::vector<VirtualServer*>& candidate_servers = host_ip_it->second;
            for (std::vector<VirtualServer*>::const_iterator server_it = candidate_servers.begin();
                 server_it != candidate_servers.end(); ++server_it) {
                VirtualServer* vs = *server_it;
                for (std::vector<std::string>::const_iterator name_it = vs->server_names_.begin();
                     name_it != vs->server_names_.end(); ++name_it) {
                    if (*name_it == target_hostname) {
                        matched_vs = vs;
                        break; // Found specific server_name match on specific IP
                    }
                }
                if (matched_vs) break;
            }
        }

        // 2. If no match on specific IP, check servers listening on 0.0.0.0 (wildcard) for the same port
        if (!matched_vs && listener_host_ip != "0.0.0.0") {
            std::map<std::string, std::vector<VirtualServer*> >::const_iterator wildcard_host_ip_it =
                hosts_on_port.find("0.0.0.0");
            if (wildcard_host_ip_it != hosts_on_port.end()) {
                const std::vector<VirtualServer*>& candidate_wildcard_servers = wildcard_host_ip_it->second;
                for (std::vector<VirtualServer*>::const_iterator server_it = candidate_wildcard_servers.begin();
                     server_it != candidate_wildcard_servers.end(); ++server_it) {
                    VirtualServer* vs = *server_it;
                    for (std::vector<std::string>::const_iterator name_it = vs->server_names_.begin();
                         name_it != vs->server_names_.end(); ++name_it) {
                        if (*name_it == target_hostname) {
                            matched_vs = vs;
                            break; // Found specific server_name match on wildcard IP
                        }
                    }
                    if (matched_vs) break;
                }
            }
        }
    }

    if (matched_vs) {
        log(LOG_DEBUG, "Matched Host header '%s' to virtual server with primary name '%s' on %s:%d",
            request_host_header_val.c_str(),
            matched_vs->server_names_.empty() ? matched_vs->host_name_.c_str() : matched_vs->server_names_[0].c_str(),
            matched_vs->host_.c_str(), matched_vs->port_);
        conn->virtual_server_ = matched_vs;
    } else {
        // No specific server_name match found, conn->virtual_server_ remains as conn->default_virtual_server_.
        log(LOG_DEBUG, "No specific virtual server for Host header '%s'. Using default for listener %s:%d (primary name '%s').",
            request_host_header_val.c_str(),
