    void WebServer::handle_connection_event(int active_fd, uint32_t events) {
        // Get the Connection object associated with the active_fd (client or pipe)
        Connection* conn = conn_manager_->get_connection_by_monitored_fd(active_fd);

        if (!conn) {
            log(LOG_ERROR, "No connection context found for active_fd '%i'. Unregistering and closing.", active_fd);
            epoll_ctl(epoll_fd_, EPOLL_CTL_DEL, active_fd, NULL); // Unregister from epoll
            close(active_fd); // Close the dangling fd
            return;
        }

        conn->update_last_activity(); // Update activity for the main connection

        // Handle errors first, as they can occur with IN/OUT events
        if (events & (EPOLLERR | EPOLLHUP)) {
            log(LOG_DEBUG, "EPOLLERR/HUP on fd %d (client_fd: %d, cgi_stdin: %d, cgi_stdout: %d)",
                active_fd, conn->client_fd_, conn->cgi_pipe_stdin_fd_, conn->cgi_pipe_stdout_fd_);

            if (active_fd == conn->client_fd_) {
                handle_error(conn); // Handles client socket errors (closes connection)
            } else if (conn->is_cgi() && (active_fd == conn->cgi_pipe_stdin_fd_ || active_fd == conn->cgi_pipe_stdout_fd_)) {
                // Error on a CGI pipe. The CgiHandler should manage this.
                // It will likely finalize the CGI operation with an error and then clean up pipes.
                cgi_handler_->handle_cgi_pipe_error(conn, active_fd);
            } else {
