**Then, add a new method to periodically check if the CGI is ready:**

````cpp

// Add this new method to CgiHandler class:

bool CgiHandler::try_register_cgi_stdout_for_reading(Connection* conn) {
    // This method should be called periodically (e.g., from a timer or main loop)
    // to check if the CGI process has started producing output

    if (conn->cgi_handler_state_ != codes::CGI_HANDLER_READING_FROM_PIPE) {
        return false; // Not in the right state
    }

    if (conn->cgi_pipe_stdout_fd_ == -1) {
        return false; // Pipe already closed
    }

    // Check if CGI process is still alive
    if (conn->cgi_pid_ > 0) {
        int status;
        pid_t result = waitpid(conn->cgi_pid_, &status, WNOHANG);
        if (result > 0) {
            // Child process has exited
            log(LOG_DEBUG, "CGI child process %d exited, registering stdout pipe for final read", conn->cgi_pid_);
            WebServer* web_server = WebServer::get_instance();
            return web_server->register_epoll_events(conn->cgi_pipe_stdout_fd_, EPOLLIN);
        } else if (result == 0) {
            // Child is still running, check if it has produced any output by doing a non-blocking read test
            char test_byte;
            ssize_t test_read = read(conn->cgi_pipe_stdout_fd_, &test_byte, 1);
            if (test_read > 0) {
                // There's data! Put it back and register with epoll
                // Unfortunately, we can't "unread" it, so we'll store it temporarily
                conn->cgi_read_buffer_.push_back(test_byte);
                log(LOG_DEBUG, "CGI has produced output, registering stdout pipe with epoll");
                WebServer* web_server = WebServer::get_instance();
                return web_server->register_epoll_events(conn->cgi_pipe_stdout_fd_, EPOLLIN);
            }
        }
    }

    return false; // Not ready yet
}
