 function, you have this line:
```cpp
// Redirect stderr to stdout (optional, but useful for debugging)
if (dup2(STDOUT_FILENO, STDERR_FILENO) == -1) {
```

This redirects the CGI script's stderr to stdout, which is correct. However, **your logging function is also writing to stderr**, and since you're in the child process, those log messages are getting mixed with the CGI script output!

**The Fix:**

You need to **stop logging in the child process** after the fork, or redirect logs elsewhere. Here are two solutions:

**Solution 1: Don't log in child process after pipe redirection**
```cpp
void CgiHandler::handle_child_pipes(int server_to_cgi_pipe[2],
                                    int cgi_to_server_pipe[2]) {
    // Close the write-end of server_to_cgi_pipe (parent uses this to write to CGI)
    close(server_to_cgi_pipe[1]);
    // Close the read-end of cgi_to_server_pipe (parent uses this to read from CGI)
    close(cgi_to_server_pipe[0]);

    // Redirect stdin to READ from server_to_cgi_pipe
    if (dup2(server_to_cgi_pipe[0], STDIN_FILENO) == -1) {
        // DON'T LOG HERE - just exit
        _exit(EXIT_FAILURE);
    }

    // Redirect stdout to WRITE to cgi_to_server_pipe
    if (dup2(cgi_to_server_pipe[1], STDOUT_FILENO) == -1) {
        // DON'T LOG HERE - just exit
        _exit(EXIT_FAILURE);
    }

    // Redirect stderr to stdout
    if (dup2(STDOUT_FILENO, STDERR_FILENO) == -1) {
        // DON'T LOG HERE - just exit
        _exit(EXIT_FAILURE);
    }

    // Close the remaining pipe file descriptors
    close(server_to_cgi_pipe[0]);
    close(cgi_to_server_pipe[1]);
}
```

**Solution 2: Redirect logs to a different file descriptor in child**
```cpp
void CgiHandler::handle_child_pipes(int server_to_cgi_pipe[2],
                                    int cgi_to_server_pipe[2]) {
    // Close the write-end of server_to_cgi_pipe (parent uses this to write to CGI)
    close(server_to_cgi_pipe[1]);
    // Close the read-end of cgi_to_server_pipe (parent uses this to read from CGI)
    close(cgi_to_server_pipe[0]);

    // Open a log file for the child process (optional)
    int log_fd = open("/tmp/cgi_child.log", O_WRONLY | O_CREAT | O_APPEND, 0644);

    // Redirect stdin to READ from server_to_cgi_pipe
    if (dup2(server_to_cgi_pipe[0], STDIN_FILENO) == -1) {
        if (log_fd >= 0) {
            dprintf(log_fd, "Failed to redirect stdin\n");
            close(log_fd);
        }
        _exit(EXIT_FAILURE);
    }

    // Redirect stdout to WRITE to cgi_to_server_pipe
    if (dup2(cgi_to_server_pipe[1], STDOUT_FILENO) == -1) {
        if (log_fd >= 0) {
            dprintf(log_fd, "Failed to redirect stdout\n");
            close(log_fd);
        }
        _exit(EXIT_FAILURE);
    }

    // Redirect stderr to stdout (for CGI script errors)
    if (dup2(STDOUT_FILENO, STDERR_FILENO) == -1) {
        if (log_fd >= 0) {
            dprintf(log_fd, "Failed to redirect stderr\n");
            close(log_fd);
        }
        _exit(EXIT_FAILURE);
    }

    if (log_fd >= 0) {
        close(log_fd);
    }

    // Close the remaining pipe file descriptors
    close(server_to_cgi_pipe[0]);
    close(cgi_to_server_pipe[1]);
}
```

**Also check your execute_cgi_script function:**
```cpp
void CgiHandler::execute_cgi_script(Connection* conn, char** envp) {
    char* script_path_cstr = const_cast<char*>(conn->script_path_.c_str());
    char* const argv[] = {script_path_cstr, NULL};

    // DON'T LOG HERE - after pipe redirection, logs go to CGI output
    // log(LOG_DEBUG, "execute_cgi_script: connection '%d' attempting to execute '%s'", ...);

    if (execve(script_path_cstr, argv, envp) == -1) {
        // DON'T LOG HERE EITHER
        _exit(EXIT_FAILURE);
    }
}
```

**Recommended approach:**
Use Solution 1 (remove logging from child process) as it's simpler and cleaner. The parent process logs are sufficient for debugging CGI execution issues.

This should resolve the issue where your CGI header parsing is trying to parse log messages instead of actual HTTP headers.

