        std::vector<char>::iterator crlf_it =
            std::search(buffer.begin(), buffer.end(), "\r\n", "\r\n" + 2);
        std::vector<char>::iterator lf_it =
            std::find(buffer.begin(), buffer.end(), '\n');

        int line_ending_length = 0;

        // Use whichever comes first
        if (crlf_it != buffer.end() &&
            (lf_it == buffer.end() || crlf_it <= lf_it)) {
            line_end_it = crlf_it;
