    struct tm* tm_info = localtime(&now);
    char log_filename[256];
    snprintf(log_filename, sizeof(log_filename), 
             "/tmp/cgi_errors_%04d%02d%02d_%02d%02d%02d.log",
             tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

    int stderr_fd = open(log_filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (stderr_fd != -1) {
        dup2(stderr_fd, STDERR_FILENO);
        close(stderr_fd);
    } else {
        // Fallback: redirect stderr to stdout
        dup2(STDOUT_FILENO, STDERR_FILENO);
    }

    // ... rest of the function ...
}
````

**Option 3: Use the same log file as your main server (if accessible)**

````cpp
void CgiHandler::handle_child_pipes(int server_to_cgi_pipe[2],
                                    int cgi_to_server_pipe[2]) {
    // ... stdin and stdout redirection code ...

