 function should use only the **path** component, not the full URI which includes the query string.

**The Problem:**
```cpp
std::string uri = conn->request_data_->uri_;  // This includes query string
```

If the URI is `/directory?param=value`, you're checking if `/directory?param=value` ends with `/`, which it doesn't, so you'd incorrectly trigger a redirect.

**The Fix:**

````cpp
bool AHandler::process_directory_redirect(Connection* conn,
                                         std::string& absolute_path) {
    // Use path instead of full URI (path excludes query string)
    std::string path = conn->request_data_->path_;

    // Check if the request path ends with a slash (indicating directory)
    bool path_ends_with_slash = !path.empty() && path[path.length() - 1] == '/';

    // Check if the absolute path is a directory
    struct stat path_stat;
    if (stat(absolute_path.c_str(), &path_stat) != 0 ||
        !S_ISDIR(path_stat.st_mode)) {
        // Not a directory or couldn't stat
        return false;
    }

    // If path doesn't end with slash, redirect to add the slash (nginx behavior)
    if (!path_ends_with_slash) {
        std::string query = conn->request_data_->query_string_;

        // Create redirect URL (path + /)
        std::string redirect_url = path + "/";

        // If there's a query string, append it
        if (!query.empty()) {
            redirect_url += "?" + query;
        }

        ErrorHandler::generate_error_response(conn, codes::MOVED_PERMANENTLY);
        conn->response_data_->set_header("Location", redirect_url);
        return true;
    }

    return false;  // No redirect needed
}
````

