## Solution 1: Delayed Epoll Registration (Recommended)

Don't register the stdout pipe immediately. Instead, register it after giving the CGI script time to start:

````cpp
// In setup_cgi_execution(), modify the parent process section:
} else {
    // Parent process
    conn->cgi_pid_ = pid;
    if (!handle_parent_pipes(conn, server_to_cgi_pipe, cgi_to_server_pipe)) {
        return false;
    }

    WebServer* web_server = WebServer::get_instance();
    if (request_method == "POST" && !conn->request_data_->body_.empty()) {
        conn->cgi_handler_state_ = codes::CGI_HANDLER_WRITING_TO_PIPE;
        // Register stdin pipe for writing
        if (!web_server->register_epoll_events(conn->cgi_pipe_stdin_fd_, EPOLLOUT)) {
            log(LOG_ERROR, "Failed to register CGI stdin pipe with epoll");
            finalize_cgi_error(conn, codes::INTERNAL_SERVER_ERROR);
            return false;
        }
    } else {
        // DON'T register stdout pipe yet - set a timer instead
        conn->cgi_handler_state_ = codes::CGI_HANDLER_READING_FROM_PIPE;

        // Close stdin pipe for GET requests
        if (conn->cgi_pipe_stdin_fd_ != -1) {
            web_server->get_conn_manager()->unregister_pipe(conn->cgi_pipe_stdin_fd_);
            close(conn->cgi_pipe_stdin_fd_);
            conn->cgi_pipe_stdin_fd_ = -1;
        }

        // Set a timestamp to delay stdout registration
        conn->cgi_start_time_ = time(NULL);  // Add this member to Connection
        log(LOG_DEBUG, "CGI: Delaying stdout pipe registration for client %d", conn->client_fd_);
    }
}
