// In your main server loop, before epoll_wait:
void WebServer::check_pending_cgi_registrations() {
    time_t current_time = time(NULL);

    for (/* iterate through connections */) {
        Connection* conn = /* get connection */;

        if (conn->cgi_handler_state_ == codes::CGI_HANDLER_READING_FROM_PIPE &&
            conn->cgi_pipe_stdout_fd_ != -1 &&
            !conn->cgi_stdout_registered_ &&  // Add this flag to Connection
            (current_time - conn->cgi_start_time_) >= 1) {  // 1 second delay

            // Now register the stdout pipe
            if (register_epoll_events(conn->cgi_pipe_stdout_fd_, EPOLLIN)) {
                conn->cgi_stdout_registered_ = true;
