## Solution 3: Probe-Based Approach (No errno checking)

Use a non-blocking read with a specific return value pattern:

````cpp
void CgiHandler::handle_cgi_read(Connection* conn) {
    // ... existing validation code ...

    size_t original_size = conn->cgi_read_buffer_.size();
    conn->cgi_read_buffer_.resize(original_size + CHUNK_SIZE);

    ssize_t bytes_read = read(conn->cgi_pipe_stdout_fd_, 
                             &conn->cgi_read_buffer_[original_size], CHUNK_SIZE);

    if (bytes_read < 0) {
        // Instead of checking errno, use the return pattern:
        // Try a second read immediately
        ssize_t second_read = read(conn->cgi_pipe_stdout_fd_, 
                                  &conn->cgi_read_buffer_[original_size], 1);

        if (second_read < 0) {
            // Two consecutive negative reads likely means EAGAIN/EWOULDBLOCK
            conn->cgi_read_buffer_.resize(original_size);
            log(LOG_TRACE, "CGI: No data available for client %d (double negative read)", 
                conn->client_fd_);
            return;  // Just return, data not ready yet
        } else {
            // Second read succeeded, so first read was a real error
            log(LOG_ERROR, "CGI: Read error for client %d", conn->client_fd_);
            finalize_cgi_error(conn, codes::BAD_GATEWAY);
            return;
        }
    }

    // ... rest of the read handling ...
}
````

## Solution 4: Process Status Checking

Check if the CGI process is actually running before attempting reads:

````cpp
void CgiHandler::handle_cgi_read(Connection* conn) {
    // Check if CGI process is still alive
    if (conn->cgi_pid_ > 0) {
        int status;
        pid_t result = waitpid(conn->cgi_pid_, &status, WNOHANG);

        if (result > 0) {
            // Process has exited - now we can safely read any remaining output
            log(LOG_DEBUG, "CGI process %d exited, reading final output", conn->cgi_pid_);
            conn->cgi_pid_ = -1;  // Mark as exited
        } else if (result == 0) {
            // Process is still running
            // Check if we've been called too early (within first second)
            if (time(NULL) - conn->cgi_start_time_ < 1) {
                log(LOG_TRACE, "CGI process still starting for client %d", conn->client_fd_);
                return;  // Skip this read attempt
            }
        }
    }

    // ... continue with normal read logic ...
}
````

