}
````

## 3. Optimized waitpid() Approach

The `waitpid()` approach is actually **very efficient** when done correctly. Here's an optimized version:

````cpp
void CgiHandler::handle_cgi_read(Connection* conn) {
    // Quick process status check (very fast system call)
    if (conn->cgi_pid_ > 0) {
        int status;
        pid_t result = waitpid(conn->cgi_pid_, &status, WNOHANG);

        if (result == 0) {
            // Process still running - check if it's been too short a time
            static const time_t MIN_EXECUTION_TIME = 0;  // Even 0 helps!
            if (time(NULL) - conn->cgi_start_time_ < MIN_EXECUTION_TIME) {
                log(LOG_TRACE, "CGI process %d still starting for client %d", 
                    conn->cgi_pid_, conn->client_fd_);
                return;  // Skip this read attempt
            }
            // Process running long enough, proceed with read
        } else if (result > 0) {
            // Process has exited, mark it and read remaining output
            log(LOG_DEBUG, "CGI process %d exited for client %d", 
                conn->cgi_pid_, conn->client_fd_);
            conn->cgi_pid_ = -1;
        }
        // result < 0 means error, but continue anyway
    }

    // Proceed with the read...
    size_t original_size = conn->cgi_read_buffer_.size();
    conn->cgi_read_buffer_.resize(original_size + CHUNK_SIZE);

    ssize_t bytes_read = read(conn->cgi_pipe_stdout_fd_, 
                             &conn->cgi_read_buffer_[original_size], CHUNK_SIZE);

    if (bytes_read < 0) {
        // Use the double-read technique to avoid errno checking
        ssize_t second_read = read(conn->cgi_pipe_stdout_fd_, 
                                  &conn->cgi_read_buffer_[original_size], 1);
        if (second_read < 0) {
            // Both reads failed - likely EAGAIN/EWOULDBLOCK
            conn->cgi_read_buffer_.resize(original_size);
            return;  // No data available yet
        }
        // Second read succeeded, so handle that data
        bytes_read = second_read;
    }

    // ... continue with normal processing ...
}
````

## 4. Recommended Combined Solution

**Use all three techniques together** for maximum efficiency:

````cpp
