} else {
    conn->cgi_handler_state_ = codes::CGI_HANDLER_READING_FROM_PIPE;

    // Register CGI stdout pipe as EDGE-TRIGGERED to avoid spurious events
    if (!web_server->register_epoll_events(conn->cgi_pipe_stdout_fd_,
                                           EPOLLIN, true)) {  // true = edge-triggered
        log(LOG_ERROR, "Failed to register CGI stdout pipe with epoll");
        finalize_cgi_error(conn, codes::INTERNAL_SERVER_ERROR);
        return false;
    }

    // Client socket remains level-triggered (default)
    log(LOG_DEBUG, "CGI: Registered stdout pipe as edge-triggered for client %d", 
        conn->client_fd_);
}
````

## Benefits of This Mixed Approach

1. **Client sockets (LT)**: Reliable, easier to handle, won't miss data
2. **CGI pipes (ET)**: Eliminates spurious events, more efficient for pipes
3. **Server sockets (LT)**: Standard approach for accepting connections
4. **File operations (LT)**: Simpler error handling

## Important Considerations for Edge-Triggered

When using ET mode for CGI pipes, you need to handle reads differently:

````cpp
void CgiHandler::handle_cgi_read(Connection* conn) {
    // With edge-triggered, you MUST read until EAGAIN/EWOULDBLOCK
    // or you might miss data

    while (true) {
        size_t original_size = conn->cgi_read_buffer_.size();
        conn->cgi_read_buffer_.resize(original_size + CHUNK_SIZE);

        ssize_t bytes_read = read(conn->cgi_pipe_stdout_fd_, 
                                 &conn->cgi_read_buffer_[original_size], 
                                 CHUNK_SIZE);

        if (bytes_read < 0) {
            // Use double-read technique to detect EAGAIN without errno
            ssize_t second_read = read(conn->cgi_pipe_stdout_fd_, 
                                      &conn->cgi_read_buffer_[original_size], 1);
            if (second_read < 0) {
                // Both reads failed - likely EAGAIN/EWOULDBLOCK
                conn->cgi_read_buffer_.resize(original_size);
                break;  // Exit the loop - no more data available
            }
            bytes_read = second_read;
        }

        if (bytes_read == 0) {
            // EOF
            conn->cgi_read_buffer_.resize(original_size);
            // Handle EOF...
            break;
        }

        // Adjust buffer to actual bytes read
        conn->cgi_read_buffer_.resize(original_size + bytes_read);

        // Process the data
        parse_cgi_output(conn);

        // Continue reading until we get EAGAIN/EWOULDBLOCK
    }
}
````

## Recommended Strategy

````cpp
// Use Level-Triggered for:
register_epoll_events(server_socket_fd, EPOLLIN, false);     // Server socket
register_epoll_events(client_socket_fd, EPOLLIN, false);     // Client sockets

// Use Edge-Triggered for:
register_epoll_events(cgi_pipe_stdout_fd, EPOLLIN, true);    // CGI pipes
register_epoll_events(cgi_pipe_stdin_fd, EPOLLOUT, true);    // CGI pipes
````

This mixed approach gives you the best of both worlds: reliable client handling with level-triggered mode and efficient CGI pipe handling with edge-triggered mode, all using a single epoll instance.

