    time_t cgi_spawn_time_;
    bool cgi_pipes_registered_;
    // ... existing members
};

// Modified setup_cgi_execution:
bool CgiHandler::setup_cgi_execution(Connection* conn) {
    // ... fork and pipe setup ...

    } else {
        // Parent process
        conn->cgi_pid_ = pid;
        conn->cgi_spawn_time_ = time(NULL);
        conn->cgi_pipes_registered_ = false;

        if (!handle_parent_pipes(conn, server_to_cgi_pipe, cgi_to_server_pipe)) {
            return false;
        }

        // DON'T register pipes immediately for GET requests
        if (request_method == "POST" && !conn->request_data_->body_.empty()) {
            conn->cgi_handler_state_ = codes::CGI_HANDLER_WRITING_TO_PIPE;
            // Register stdin immediately for POST
            web_server->register_epoll_events(conn->cgi_pipe_stdin_fd_, EPOLLOUT, true);
        } else {
            conn->cgi_handler_state_ = codes::CGI_HANDLER_READING_FROM_PIPE;
            // Will register stdout pipe later via delayed registration
            log(LOG_DEBUG, "CGI: Delaying stdout pipe registration for client %d", 
                conn->client_fd_);
        }
    }
}

// Add to your main event loop:
void WebServer::process_delayed_cgi_registrations() {
    time_t current_time = time(NULL);

    for (auto& conn_pair : connections_) {
        Connection* conn = conn_pair.second;

        if (conn->cgi_handler_state_ == codes::CGI_HANDLER_READING_FROM_PIPE &&
            !conn->cgi_pipes_registered_ &&
            conn->cgi_pipe_stdout_fd_ != -1 &&
            (current_time - conn->cgi_spawn_time_) >= 1) {

            // Register with edge-triggered mode
            if (register_epoll_events(conn->cgi_pipe_stdout_fd_, EPOLLIN, true)) {
                conn->cgi_pipes_registered_ = true;
                log(LOG_DEBUG, "CGI: Delayed registration of stdout pipe for client %d", 
                    conn->client_fd_);
            }
        }
    }
}
````

## Key Nginx Insights:

1. **Avoid the race condition entirely** with delayed registration
2. **Use edge-triggered epoll** for CGI pipes specifically
3. **Process pooling** when possible (FastCGI model)
4. **State machines** instead of blocking operations
5. **Timer-based delayed registration** for synchronization

The **delayed registration** approach is the most practical solution for your use case and mirrors how production web servers handle this exact problem.

