bool set_non_blocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags == -1) {
        log(LOG_ERROR, "fcntl(F_GETFL) for fd %d failed: %s", fd, strerror(errno));
        return false;
    }
    if (fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) {
        log(LOG_ERROR, "fcntl(F_SETFL, O_NONBLOCK) for fd %d failed: %s", fd, strerror(errno));
        return false;
    }
    log(LOG_DEBUG, "Set fd %d to non-blocking", fd);
    return true;
}

bool register_epoll_events(int fd, uint32_t events) {
    WebServer* server = WebServer::get_instance();
    if (!server) {
        log(LOG_ERROR, "WebServer instance is NULL in register_epoll_events");
        return false;
    }
    // Accessing private member epoll_fd_ via friend status
    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev)); // Good practice
    ev.events = events;
    ev.data.fd = fd;
    if (epoll_ctl(server->epoll_fd_, EPOLL_CTL_ADD, fd, &ev) < 0) {
        log(LOG_ERROR, "Failed to register fd %d on epoll: %s", fd, strerror(errno));
        return false;
    }
    log(LOG_DEBUG, "Registered fd %d on epoll with events %u", fd, events);
    return true;
}

