codes::ParseStatus RequestParser::parse(Connection* conn) {
    log(LOG_DEBUG, "Starting parsing attempt on Connection '%i'",
        conn->client_fd_);

    if (conn->parser_state_ == codes::PARSING_COMPLETE) {
        return codes::PARSE_SUCCESS;  // Already complete
    }

    codes::ParseStatus current_step_status = codes::PARSE_INCOMPLETE;

    // Loop as long as the state is not terminal (COMPLETE or ERROR)
    while (conn->parser_state_ != codes::PARSING_COMPLETE &&
           conn->parser_state_ != codes::PARSING_ERROR) {

        // If the buffer is empty AND we are not in a state that can complete without more input
        // (e.g. headers were parsed, and it was a GET request, so body parsing is skipped and state becomes COMPLETE)
        // then we must be incomplete.
        if (conn->read_buffer_.empty() && conn->parser_state_ != codes::PARSING_COMPLETE) {
             // This check might be too simplistic, as some states might transition to COMPLETE
             // even with an empty buffer if all necessary information for that state was processed.
             // The key is that if a sub-parser needs data from the buffer and it's empty, it will return PARSE_INCOMPLETE.
            log(LOG_DEBUG, "Parse: Buffer is empty and parsing is not yet complete. Current state: %d", conn->parser_state_);
            // It's generally better to let the sub-parser determine if it's incomplete.
            // If we reach here, it means a previous step consumed the buffer.
        }

        switch (conn->parser_state_) {
            case codes::PARSING_REQUEST_LINE:
                current_step_status = parse_request_line(conn);
                break;
            case codes::PARSING_HEADERS:
                current_step_status = parse_headers(conn);
                break;
            case codes::PARSING_BODY:
                current_step_status = parse_body(conn);
                break;
            case codes::PARSING_CHUNKED_BODY:
                current_step_status = parse_chunked_body(conn);
                break;
            // PARSING_COMPLETE and PARSING_ERROR are handled by the main while loop condition
            default:
                log(LOG_FATAL, "Parse: Invalid parser state encountered: %d", conn->parser_state_);
                conn->parser_state_ = codes::PARSING_ERROR; // Set error state
                current_step_status = codes::PARSE_ERROR;   // Or a more specific error
                break; 
        }

        // If the current parsing step is incomplete, or an error occurred,
        // or the parser was set to an error state internally by a sub-parser.
        if (current_step_status != codes::PARSE_SUCCESS && current_step_status != codes::PARSE_HEADERS_COMPLETE) {
            // PARSE_HEADERS_COMPLETE is a "successful" outcome for parse_headers, allowing transition.
            // Any other status that isn't a definitive success for the *current step* (like PARSE_INCOMPLETE or an error code)
            // means we should stop and return that status.
