codes::ParseStatus RequestParser::parse(Connection* conn) {
    log(LOG_DEBUG, "Parse: Entry. Client %i, Current state: %d, Buffer size: %zu",
        conn->client_fd_, conn->parser_state_, conn->read_buffer_.size());

    if (conn->parser_state_ == codes::PARSING_COMPLETE) {
        return codes::PARSE_SUCCESS;
    }
    if (conn->parser_state_ == codes::PARSING_ERROR) {
        return codes::PARSE_ERROR; // Or a more specific error if stored
    }

    // If we were waiting for data, and parse() is called again,
    // it implies more data might have arrived. Revert to the actual parsing state.
    if (conn->parser_state_ == codes::PARSING_WAITING_FOR_DATA) {
        // Only revert if there's actually new data to process, or if it's the first time
        // re-entering parse() after being told to wait.
        // A simple heuristic: if buffer is empty, we definitely still need to wait.
        // However, the sub-parser will make the final call if the new data is still insufficient.
        if (conn->read_buffer_.empty()) {
             log(LOG_DEBUG, "Parse: Was WAITING_FOR_DATA, buffer still empty. Client %i. Returning PARSE_INCOMPLETE.", conn->client_fd_);
             return codes::PARSE_INCOMPLETE;
        }
        log(LOG_DEBUG, "Parse: Was WAITING_FOR_DATA, reverting to state %d to retry. Client %i.",
            conn->client_fd_, conn->state_before_waiting_for_data_);
        conn->parser_state_ = conn->state_before_waiting_for_data_;
    }

    codes::ParseStatus current_step_status = codes::PARSE_INCOMPLETE; // Default for safety

    // Loop as long as the state is not terminal (COMPLETE, ERROR, or WAITING_FOR_DATA)
    while (conn->parser_state_ != codes::PARSING_COMPLETE &&
           conn->parser_state_ != codes::PARSING_ERROR &&
           conn->parser_state_ != codes::PARSING_WAITING_FOR_DATA) {

