        // but also doesn't complete its task, the sub-parser should return PARSE_INCOMPLETE.
        // This check is more of a safeguard if a sub-parser doesn't handle empty buffer correctly.
        if (conn->read_buffer_.empty() &&
            (conn->parser_state_ == codes::PARSING_REQUEST_LINE ||
             conn->parser_state_ == codes::PARSING_HEADERS ||
             conn->parser_state_ == codes::PARSING_BODY || // If body parsing expects data
             conn->parser_state_ == codes::PARSING_CHUNKED_BODY)) { // If chunked parsing expects data
            log(LOG_DEBUG, "Parse: Buffer empty mid-parsing state %d. Client %i. Breaking to return INCOMPLETE.",
                conn->client_fd_, conn->parser_state_);
            current_step_status = codes::PARSE_INCOMPLETE;
            break; // Exit while loop, will return PARSE_INCOMPLETE
        }


        log(LOG_DEBUG, "Parse: Loop. Client %i, State: %d", conn->client_fd_, conn->parser_state_);
        switch (conn->parser_state_) {
            case codes::PARSING_REQUEST_LINE:
                current_step_status = parse_request_line(conn);
                break;
            case codes::PARSING_HEADERS:
                current_step_status = parse_headers(conn);
                break;
            case codes::PARSING_BODY:
                current_step_status = parse_body(conn);
                break;
            case codes::PARSING_CHUNKED_BODY:
