                conn->parser_state_ = codes::PARSING_ERROR;
                current_step_status = codes::PARSE_ERROR; // Or a more specific error
                break;
        }

        // If a sub-parser indicated an error or completion, the state would change,
        // and the while loop condition will handle it.
        // If a sub-parser set state to PARSING_WAITING_FOR_DATA, the loop also exits.
        // If a sub-parser returned PARSE_INCOMPLETE *without* changing state to WAITING_FOR_DATA,
