        // This design relies on sub-parsers to set WAITING_FOR_DATA if they return PARSE_INCOMPLETE
        // and want the main loop to wait.
        if (current_step_status != codes::PARSE_SUCCESS && current_step_status != codes::PARSE_HEADERS_COMPLETE) {
             // If a step is not fully successful (e.g. PARSE_INCOMPLETE, or an error code)
             // and it didn't change the state to WAITING_FOR_DATA or ERROR,
             // we should break here to reflect that status.
             // However, with the WAITING_FOR_DATA state change, this might not be strictly needed
             // if sub-parsers always change state appropriately.
             log(LOG_DEBUG, "Parse: Step for state %d returned %d. Client %i. Breaking from loop.",
                 conn->client_fd_, conn->parser_state_, current_step_status);
             break; // Exit while loop
        }
    }

    // Determine final status based on parser_state_
    if (conn->parser_state_ == codes::PARSING_COMPLETE) {
        log(LOG_DEBUG, "Parse: Final status PARSE_SUCCESS. Client %i.", conn->client_fd_);
        return codes::PARSE_SUCCESS;
    } else if (conn->parser_state_ == codes::PARSING_ERROR) {
        log(LOG_ERROR, "Parse: Final status PARSE_ERROR. Client %i.", conn->client_fd_);
        return codes::PARSE_ERROR; // Or a more specific error code if available
    } else if (conn->parser_state_ == codes::PARSING_WAITING_FOR_DATA) {
        log(LOG_DEBUG, "Parse: Final status PARSE_INCOMPLETE (was waiting). Client %i.", conn->client_fd_);
        return codes::PARSE_INCOMPLETE;
    }

    // Fallback: if the loop exited due to current_step_status not being success,
    // and state isn't one of the above, return that status.
    log(LOG_DEBUG, "Parse: Fallback, returning current_step_status %d. Client %i. State: %d",
        current_step_status, conn->client_fd_, conn->parser_state_);
    return current_step_status; // This would typically be PARSE_INCOMPLETE from the break
}
