        // conn->parser_state_ (e.g., to PARSING_BODY or PARSING_COMPLETE for GET/HEAD).
    }

    // Attempt to parse the body if that's the current state
    if (conn->parser_state_ == codes::PARSING_BODY) {
        status = parse_body(conn); // Or parse_chunked_body if applicable
        if (status != codes::PARSE_SUCCESS) { // PARSE_SUCCESS means body is fully parsed
            // If incomplete or error, return that status immediately.
            // parse_body should set conn->parser_state_ to PARSING_ERROR on error.
            log(LOG_DEBUG, "Parse: parse_body returned %d. Client %i.", status, conn->client_fd_);
