                conn->parser_state_ = codes::PARSING_ERROR;
                return codes::PARSE_HEADER_TOO_LONG; // Or a more generic error
            }
            log(LOG_DEBUG, "parse_headers: Incomplete header line. Need more data. Client %i.", conn->client_fd_);
            return codes::PARSE_INCOMPLETE;
        }

        // We found a CRLF, so we have at least one line.
        std::string header_line(buffer.begin(), line_end);
        buffer.erase(buffer.begin(), line_end + 2); // Consume the line + CRLF

        if (header_line.empty()) {
            // This is the empty line signifying the end of headers.
            headers_complete_marker_found = true;
            log(LOG_DEBUG, "parse_headers: Empty line found, headers complete. Client %i.", conn->client_fd_);
            break; // Exit the while loop for header lines
        }

