        //   conn->parser_state_ = codes::PARSING_ERROR;
        //   return codes::PARSE_INVALID_HEADER; // Or appropriate error
    }

    if (headers_complete_marker_found) {
        // Transition to the next state based on request type, method, etc.
        // Example:
        if (conn->request_data_->method_ == "POST" || conn->request_data_->method_ == "PUT") {
            if (conn->request_data_->headers_.count("transfer-encoding") &&
                conn->request_data_->get_header("transfer-encoding") == "chunked") {
                conn->parser_state_ = codes::PARSING_CHUNKED_BODY;
            } else if (conn->request_data_->headers_.count("content-length")) {
                // Convert content-length to size_t, handle potential errors
                try {
                    conn->request_data_->content_length_ = std::stoul(conn->request_data_->get_header("content-length"));
                    if (conn->request_data_->content_length_ == 0) {
                        conn->parser_state_ = codes::PARSING_COMPLETE; // No body to parse
                    } else {
                        conn->parser_state_ = codes::PARSING_BODY;
                    }
                } catch (const std::exception& e) {
                    log(LOG_ERROR, "Invalid Content-Length value. Client %i.", conn->client_fd_);
                    conn->parser_state_ = codes::PARSING_ERROR;
                    return codes::PARSE_INVALID_HEADER; // Or specific content length error
                }
            } else {
                // No Content-Length for POST/PUT without chunked is usually an error (or implies 0 length for some interpretations)
                // For simplicity, let's assume 0 if not specified for POST/PUT and not chunked.
                // Or, make it an error:
                // log(LOG_ERROR, "POST/PUT request without Content-Length or Transfer-Encoding: chunked. Client %i.", conn->client_fd_);
                // conn->parser_state_ = codes::PARSING_ERROR;
                // return codes::PARSE_LENGTH_REQUIRED;
                conn->request_data_->content_length_ = 0;
                conn->parser_state_ = codes::PARSING_COMPLETE;
