                                       bool& need_autoindex) {
    // Ensure absolute_path ends with /
    if (absolute_path.empty() || absolute_path[absolute_path.length() - 1] != '/') { // Added check for empty string
        absolute_path += '/';
    }

    // Get location config
    const Location* location = conn->location_match_;
    if (!location) { // Safety check
        ErrorHandler::generate_error_response(conn, codes::INTERNAL_SERVER_ERROR);
        log(LOG_ERROR, "process_directory_index: No location match found for connection %d", conn->client_fd_);
        return false;
    }
    std::string index = location->index_;

    if (!index.empty()) {
        std::string index_path_candidate = absolute_path + index; // Use a temporary variable
        struct stat index_stat;
        // Check if index file exists and is a regular file
        if (stat(index_path_candidate.c_str(), &index_stat) == 0 &&
            S_ISREG(index_stat.st_mode)) {
            // Index file exists, update path to use it
            absolute_path = index_path_candidate; // Modify the referenced absolute_path
            log(LOG_DEBUG, "process_directory_index: Found index file: %s", absolute_path.c_str());
            need_autoindex = false; // Explicitly set, as we found an index
            return true;  // Found and using index file
        }
    }

    // No index file found, check if autoindex is enabled
    if (location->autoindex_) {
        need_autoindex = true;
        log(LOG_DEBUG,
            "process_directory_index: No index file found, autoindex enabled "
            "for %s",
            absolute_path.c_str());
        return true;  // Will use autoindex (absolute_path is the directory path)
    }

    // No index file and autoindex is disabled
    // Fluxogram 403 - autoindex off - call error handler
    ErrorHandler::generate_error_response(conn, codes::FORBIDDEN);
    log(LOG_DEBUG,
        "process_directory_index: No index file and autoindex disabled for %s",
        absolute_path.c_str());
    need_autoindex = false; // Explicitly set
    return false;  // Error response set
}
