````cpp
// This function should be called after the request line is parsed.
// It modifies the request object in place.
bool normalize_and_validate_request_path(HttpRequest* request) {
    // 1. Get the raw path from the full URI
    std::string raw_path;
    size_t query_pos = request->uri_.find('?');
    if (query_pos != std::string::npos) {
        raw_path = request->uri_.substr(0, query_pos);
    } else {
        raw_path = request->uri_;
    }

    // 2. Decode the path. Your decode_uri_path is a good start.
    // This step MUST reject %00 and other dangerous encodings.
    std::string decoded_path = RequestParser::decode_uri_path(raw_path);
    if (decoded_path.empty()) {
        return false; // Decoding failed
    }

    // 3. Normalize the DECODED path to prevent traversal.
    // This is the most critical step.
    std::vector<std::string> segments;
    std::string current_segment;
    std::istringstream iss(decoded_path);

    // Handle the leading slash
    if (decoded_path.empty() || decoded_path[0] != '/') {
        // Not an origin-form path, handle as an error or special case.
    }

    // Split by '/'
    while(std::getline(iss, current_segment, '/')) {
        if (current_segment.empty() || current_segment == ".") {
            // Ignore empty or '.' segments
            continue;
        }
        if (current_segment == "..") {
            if (!segments.empty()) {
                segments.pop_back(); // Go up one level
            }
            // If segments is empty, we are at the root.
            // A ".." here is ignored, preventing traversal above root.
        } else {
            segments.push_back(current_segment);
        }
    }

    // 4. Reconstruct the canonical path
    std::string canonical_path = "/";
    for (size_t i = 0; i < segments.size(); ++i) {
        canonical_path += segments[i] + (i == segments.size() - 1 ? "" : "/");
    }

    // 5. Store the clean, safe path in the request object.
    request->path_ = canonical_path;

    return true;
}
````

**Conclusion:** Nginx does not choose one or the other; it intelligently does both at the appropriate time. Your parser should too.
1.  **Inside the state machine:** Check for syntactically invalid characters.
2.  **After the state machine:** Decode and then normalize the path to prevent semantic attacks like path traversal.

