                } else if (buff.read_ptr() - context.value_start_ >= http_limits::MAX_HEADER_VALUE_LENGTH) {
                    return codes::PARSE_ERROR;
                }
                break;

            case HeadParseState::VALUE_ALMOST_DONE:
                if (ch == '\n') {
                    commit_header(conn, context);
                    state = HeadParseState::LINE_START;
                } else {
                    return codes::PARSE_ERROR;
                }
