                } else if (buff.read_ptr() - context.key_start_ >= http_limits::MAX_HEADER_NAME_LENGTH) {
                    return codes::PARSE_ERROR;
                }
                break;

            case HeadParseState::SPACE_BEFORE_VALUE:
                if (ch == ' ' || ch == '\t') {
                    break; // Skip whitespace
                }
                context.value_start_ = buff.read_ptr();
                state = HeadParseState::VALUE;
                continue;

            case HeadParseState::VALUE:
                if (ch == '\r') {
                    context.value_end_ = buff.read_ptr();
                    state = HeadParseState::VALUE_ALMOST_DONE;
                } else if (ch == '\n') { // Tolerate bare LF
                    context.value_end_ = buff.read_ptr();
                    commit_header(conn, context);
                    state = HeadParseState::LINE_START;
                } else if (iscntrl(ch) && ch != '\t') {
                    return codes::PARSE_ERROR;
                } else if (buff.read_ptr() - context.value_start_ >= http_limits::MAX_HEADER_VALUE_LENGTH) {
                    return codes::PARSE_ERROR;
                }
                break;

            case HeadParseState::VALUE_ALMOST_DONE:
                if (ch == '\n') {
                    commit_header(conn, context);
                    state = HeadParseState::LINE_START;
                } else {
                    return codes::PARSE_ERROR;
                }
                break;

            case HeadParseState::HEADERS_ALMOST_DONE:
                if (ch == '\n') {
                    // Headers are parsed. Now they must be validated.
                    return codes::PARSE_HEADERS_COMPLETE;
                } else {
                    return codes::PARSE_ERROR;
                }
                break;
        }

        buff.has_read(1);
        if (conn->read_buffer_.processed_bytes() > http_limits::MAX_REQUEST_HEAD_SIZE) {
            log(LOG_WARNING, "Request head size exceeds limit");
            return codes::PARSE_HEADER_TOO_LONG;
        }
    }

    return codes::PARSE_INCOMPLETE;
}

// Helper function to commit the parsed header, normalizing the key to lowercase.
void RequestParser::commit_header(Connection* conn, ParserContext& context) {
    std::string key(context.key_start_, context.key_end_ - context.key_start_);
    // Normalize header name to lowercase for case-insensitive lookup
    for (size_t i = 0; i < key.length(); ++i) {
        key[i] = std::tolower(key[i]);
    }

    // Trim leading/trailing whitespace from value
    const char* val_start = context.value_start_;
    const char* val_end = context.value_end_;
    while (val_start < val_end && (*val_start == ' ' || *val_start == '\t')) {
        val_start++;
    }
    while (val_end > val_start && (*(val_end - 1) == ' ' || *(val_end - 1) == '\t')) {
        val_end--;
    }
    std::string value(val_start, val_end - val_start);

    conn->request_data_->headers_[key] = value;
    log(LOG_TRACE, "Header committed: '%s': '%s'", key.c_str(), value.c_str());

    // Reset pointers for the next header
    context.key_start_ = NULL;
    context.key_end_ = NULL;
    context.value_start_ = NULL;
    context.value_end_ = NULL;
}

