    }

    // 2. Extract and trim the header value.
    // RFC 7230 allows for optional whitespace around the value.
    std::string header_value;
    if (context.value_start_ && context.value_end_) {
        const char* start = context.value_start_;
        const char* end = context.value_end_;

        // Trim trailing whitespace (leading is handled by the parser state)
        while (end > start && (*(end - 1) == ' ' || *(end - 1) == '\t')) {
            end--;
