Here is the recommended workflow:

````cpp
// This logic should run right after parse_headers returns PARSE_HEADERS_COMPLETE

// 1. Get the header string
std::string cl_header = conn->request_data_->get_header("content-length");
if (!cl_header.empty()) {
    // 2. Convert string to size_t safely
    char* end;
    long long_len = std::strtol(cl_header.c_str(), &end, 10);

    // Check for conversion errors: no digits found, or extra chars after digits
    if (end == cl_header.c_str() || *end != '\0' || long_len < 0) {
        return codes::PARSE_ERROR; // Invalid Content-Length value
    }

    // Check against server limits
    if (static_cast<size_t>(long_len) > http_limits::MAX_CONTENT_LENGTH) {
        return codes::PARSE_CONTENT_TOO_LARGE;
    }

    // 3. Store the numeric value in the request object
    conn->request_data_->content_length_ = static_cast<size_t>(long_len);
}

// Now, your parse_body function becomes very simple and efficient
codes::ParseStatus RequestParser::parse_body(Connection* conn) {
    log(LOG_DEBUG, "Parsing body for connection: %i", conn->client_fd_);

    Buffer&      buff = conn->read_buffer_;
    HttpRequest* req = conn->request_data_;

    // The target size is already parsed and stored.
    size_t bytes_to_read = req->content_length_ - req->body_.size();
    size_t bytes_in_buffer = buff.readable_bytes();

    size_t bytes_to_move = std::min(bytes_to_read, bytes_in_buffer);

    if (bytes_to_move > 0) {
        // Append the data from the read buffer to the body vector
        req->body_.insert(req->body_.end(), buff.read_ptr(), buff.read_ptr() + bytes_to_move);
        buff.has_read(bytes_to_move);
    }

    // Check if we are done
    if (req->body_.size() == req->content_length_) {
        return codes::PARSE_SUCCESS;
    }

    // If we are here, we need more data.
    return codes::PARSE_INCOMPLETE;
}
````

