codes::ParseStatus WebServer::process_request(Connection* conn) {
    log(LOG_DEBUG, "Processing request for connection: %i", conn->client_fd_);
    HttpRequest* request = conn->request_data_;

    // --- Phase 1: Establish Context ---
    // 1a. Match Host header to a virtual server.
    match_host_header(conn);
    if (!conn->virtual_server_) {
        log(LOG_FATAL, "Connection %i has no virtual server context.", conn->client_fd_);
        return codes::PARSE_ERROR; // Should be caught by default server logic
    }

    // 1b. Match URI to a location block.
    conn->location_match_ = find_matching_location(conn->virtual_server_, request->path_);
    if (!conn->location_match_) {
        return codes::PARSE_NO_LOCATION_MATCH; // Will become a 404
    }

    // --- Phase 2: Validate Request (The Gauntlet) ---
    // 2c. Validate HTTP version.
    if (request->version_ != "HTTP/1.1" && request->version_ != "HTTP/1.0") {
        return codes::PARSE_UNSUPPORTED_VERSION; // 505
    }
    if (request->version_ == "HTTP/1.1" && request->get_header("host").empty()) {
        return codes::PARSE_MISSING_HOST_HEADER; // 400
    }

    // 2d. Validate request method against the location's rules.
    if (!validate_request_method(conn)) { // This function should just return bool
        return codes::PARSE_METHOD_NOT_ALLOWED; // 405
    }

    // 2e. Validate headers related to the request body.
    codes::ParseStatus body_header_status = validate_body_headers(conn);
    if (body_header_status != codes::PARSE_SUCCESS) {
        return body_header_status; // 400, 411, 413, etc.
    }

    // 2f. Validate Permissions (The Final Check before body/handler)
    if (!check_permissions(conn)) { // A new, focused function
        return codes::PARSE_FORBIDDEN; // 403
    }

    // --- Phase 3: Prepare for Execution ---
    // All checks passed. The request is valid. Now determine the next step.
    log(LOG_DEBUG, "Request for connection %i validated successfully.", conn->client_fd_);
    conn->conn_state_ = determine_body_handling_state(conn);

    // If we are not parsing a body, we can choose the handler now.
    if (conn->conn_state_ == codes::GENERATING_RESPONSE) {
        conn->active_handler_ = choose_handler(conn);
    }

    return codes::PARSE_SUCCESS;
}
