// ...existing code...
codes::WriteStatus ResponseWriter::write_response(Connection* conn, int epoll_fd) {
    // This function is now called ONLY when an EPOLLOUT event is received.

    // Send the response
    ssize_t bytes_written =
        send(conn->client_fd_,
             conn->write_buffer_.data() + conn->write_buffer_offset_,
             conn->write_buffer_.size() - conn->write_buffer_offset_,
             MSG_NOSIGNAL);

    if (bytes_written <= 0) {
        // Since we only got here on EPOLLOUT, this is a fatal error.
        log(LOG_WARNING, "Fatal write error on socket %d. Closing connection.", conn->client_fd_);
        return codes::WRITE_ERROR;
    }

    // Update the offset and progress timestamp
    conn->write_buffer_offset_ += bytes_written;
    conn->last_progress_ = time(NULL); // We made progress!

    // Check if we've written everything
    if (conn->write_buffer_offset_ == conn->write_buffer_.size()) {
        // Buffer is now empty. We are no longer interested in writing.
        // Modify epoll to stop listening for EPOLLOUT.
        struct epoll_event event;
        event.events = EPOLLIN | EPOLLET; // Or your default flags
        event.data.ptr = conn;
        if (epoll_ctl(epoll_fd, EPOLL_CTL_MOD, conn->client_fd_, &event) == -1) {
            log(LOG_ERROR, "epoll_ctl: Failed to remove EPOLLOUT for fd %d", conn->client_fd_);
            return codes::WRITE_ERROR;
        }
        return codes::WRITE_SUCCESS;
    }

    // More data to send, leave EPOLLOUT registered.
    return codes::WRITE_INCOMPLETE;
}

// This function is called when you have data ready to be sent.
bool ResponseWriter::prepare_and_arm_write(Connection* conn, int epoll_fd) {
    // If the buffer is already armed for writing, do nothing.
    if (!conn->write_buffer_.empty()) {
        return true;
    }

    // Write headers and body into conn->write_buffer_
    if (!write_headers(conn) || !write_body(conn)) {
        return false;
    }

    // If we added data to a previously empty buffer, we must arm EPOLLOUT.
    if (!conn->write_buffer_.empty()) {
        struct epoll_event event;
        event.events = EPOLLIN | EPOLLOUT | EPOLLET; // Add EPOLLOUT
        event.data.ptr = conn;
        if (epoll_ctl(epoll_fd, EPOLL_CTL_MOD, conn->client_fd_, &event) == -1) {
            log(LOG_ERROR, "epoll_ctl: Failed to add EPOLLOUT for fd %d", conn->client_fd_);
            return false;
        }
    }
    return true;
}
