switch (ctx->type) {
    case IOContext::CLIENT_SOCKET:
        handle_client_socket_event(conn, events);
        break;

    case IOContext::STATIC_FILE:
        handle_static_file_event(conn, events);
        break;

    case IOContext::CGI_PIPE_READ:
        handle_cgi_read_event(conn, events);
