**Step 2: Implement the Helper**

This function will find the context, remove it from epoll, close the FD, delete the object, and erase the pointer from the vector.

````cpp

#include "Connection.hpp"
#include <algorithm> // For std::find

// ... other Connection methods ...

void Connection::remove_io_context(IOContext* ctx_to_remove, int epoll_fd) {
    if (!ctx_to_remove) {
        return;
    }

    // Find the context in our vector
    std::vector<IOContext*>::iterator it =
        std::find(io_contexts_.begin(), io_contexts_.end(), ctx_to_remove);

    if (it == io_contexts_.end()) {
        // This indicates a logic error - trying to remove a context that
        // doesn't belong to this connection or was already removed.
        log(LOG_ERROR, "Attempted to remove an unknown or stale IOContext.");
        return;
    }

    // 1. Unregister from epoll BEFORE closing the FD
    epoll_ctl(epoll_fd, EPOLL_CTL_DEL, ctx_to_remove->fd, NULL);

    // 2. Close the file descriptor
    close(ctx_to_remove->fd);

    // 3. Erase the pointer from the vector
    io_contexts_.erase(it);

    // 4. NOW it is safe to delete the object itself
    delete ctx_to_remove;
}
````

